INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dwhLegFPPQa', 4, '{"title":"第1019018条・辨可发汗病脉证并治第十六","description":"<p>19、太阳病。脉浮紧无汗。发热。身疼痛。八九日不解。表证仍在。当复发汗。服汤已。微除。其人发烦。目瞑剧者。必衄。衄乃解。所以然者。阳气重故也。属$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019018,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '19、太阳病。脉浮紧无汗。发热。身疼痛。八九日不解。表证仍在。当复发汗。服汤已。微除。其人发烦。目瞑剧者。必衄。衄乃解。所以然者。阳气重故也。属$f{麻黄汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z2sUsMwlwcP', 4, '{"title":"第1019019条・辨可发汗病脉证并治第十六","description":"<p>20、脉浮者。病在表。可发汗。属$f{麻黄汤}。$a{（一法用$f{桂枝汤}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019019,"note":"","videoMemo":"","fangList":["麻黄汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '20、脉浮者。病在表。可发汗。属$f{麻黄汤}。$a{（一法用$f{桂枝汤}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ryUD0nHeCIt', 4, '{"title":"第1019020条・辨可发汗病脉证并治第十六","description":"<p>21、伤寒不大便六七日。头痛有热者。与承气汤。其小便清者。$a{（一云大便青。）}知不在里。续在表也。当须发汗。若头痛者。必衄。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019020,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '21、伤寒不大便六七日。头痛有热者。与承气汤。其小便清者。$a{（一云大便青。）}知不在里。续在表也。当须发汗。若头痛者。必衄。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SZ9XAj8KEep', 4, '{"title":"第1019021条・辨可发汗病脉证并治第十六","description":"<p>22、下利腹胀满。身体疼痛者。先温其里。乃攻其表。温里。宜$f{四逆汤}。攻表。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019021,"note":"","videoMemo":"","fangList":["四逆汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '22、下利腹胀满。身体疼痛者。先温其里。乃攻其表。温里。宜$f{四逆汤}。攻表。宜$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
