INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l7RSZGY7iiF', 4, '{"title":"第1019025条・辨可发汗病脉证并治第十六","description":"<p>26、太阳病。发热汗出者。此为荣弱卫强。故使汗出。欲救邪风。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019025,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '26、太阳病。发热汗出者。此为荣弱卫强。故使汗出。欲救邪风。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
