INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZIunjK0jjQq', 4, '{"title":"第1019027条・辨可发汗病脉证并治第十六","description":"<p>28、太阳病初服$f{桂枝汤}。反烦不解者。先刺风池风府。却与$f{桂枝汤}则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019027,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '28、太阳病初服$f{桂枝汤}。反烦不解者。先刺风池风府。却与$f{桂枝汤}则愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
