INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8LquyBu7lqG', 4, '{"title":"第1019035条・辨可发汗病脉证并治第十六","description":"<p>36、太阳与阳明合病。喘而胸满者。不可下。属$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019035,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '36、太阳与阳明合病。喘而胸满者。不可下。属$f{麻黄汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FqDfeKRbVje', 4, '{"title":"第1019036条・辨可发汗病脉证并治第十六","description":"<p>37、太阳中风。脉浮紧。发热恶寒。身疼痛。不汗出而烦躁者。$f{大青龙汤}主之。若脉微弱。汗出恶风者。不可服之。服之则厥逆。筋愓肉瞤。此为逆也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019036,"note":"","videoMemo":"","fangList":["大青龙汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '37、太阳中风。脉浮紧。发热恶寒。身疼痛。不汗出而烦躁者。$f{大青龙汤}主之。若脉微弱。汗出恶风者。不可服之。服之则厥逆。筋愓肉瞤。此为逆也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yIug6wgGr1t', 4, '{"title":"第1019037条・辨可发汗病脉证并治第十六","description":"<p>39、阳明中风。脉弦浮大而短气。腹都满。胁下及心痛。久按之。气不通。鼻干不得汗。嗜卧。一身及目悉黄。小便难。有潮热。时时哕。耳前后肿。刺之小差。外不解。过十日。脉续浮者。与$f{小柴胡汤}。脉但浮。无余证者。与$f{麻黄汤}。不溺腹满。加哕者不治。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019037,"note":"","videoMemo":"","fangList":["小柴胡汤","麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '39、阳明中风。脉弦浮大而短气。腹都满。胁下及心痛。久按之。气不通。鼻干不得汗。嗜卧。一身及目悉黄。小便难。有潮热。时时哕。耳前后肿。刺之小差。外不解。过十日。脉续浮者。与$f{小柴胡汤}。脉但浮。无余证者。与$f{麻黄汤}。不溺腹满。加哕者不治。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ei06gJwTojn', 4, '{"title":"第1019038条・辨可发汗病脉证并治第十六","description":"<p>40、太阳病。十日以去。脉浮而细。嗜卧者。外已解也。设胸满胁痛者。与$f{小柴胡汤}。脉但浮者。与$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019038,"note":"","videoMemo":"","fangList":["小柴胡汤","麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '40、太阳病。十日以去。脉浮而细。嗜卧者。外已解也。设胸满胁痛者。与$f{小柴胡汤}。脉但浮者。与$f{麻黄汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BjPIJT4W2e8', 4, '{"title":"第1019039条・辨可发汗病脉证并治第十六","description":"<p>41、伤寒脉浮缓。身不疼。但重。乍有轻时。无少阴证者。可与$f{大青龙汤}发之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019039,"note":"","videoMemo":"","fangList":["大青龙汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '41、伤寒脉浮缓。身不疼。但重。乍有轻时。无少阴证者。可与$f{大青龙汤}发之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DM2Ocz0GvjC', 4, '{"title":"第1019040条・辨可发汗病脉证并治第十六","description":"<p>42、伤寒表不解。心下有水气。干呕发热而咳。或渴。或利。或噎。或小便不利。少腹满。或喘者。宜$f{小青龙汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019040,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '42、伤寒表不解。心下有水气。干呕发热而咳。或渴。或利。或噎。或小便不利。少腹满。或喘者。宜$f{小青龙汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p9Y34lRUwbl', 4, '{"title":"第1019041条・辨可发汗病脉证并治第十六","description":"<p>43、伤寒心下有水气。咳而微喘。发热不渴。服汤已渴者。此寒去欲解也。属$f{小青龙汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019041,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '43、伤寒心下有水气。咳而微喘。发热不渴。服汤已渴者。此寒去欲解也。属$f{小青龙汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YCRSzKjE7E9', 4, '{"title":"第1019042条・辨可发汗病脉证并治第十六","description":"<p>44、中风往来寒热。伤寒五六日以后。胸胁苦满。嘿嘿不欲饮食。烦心。喜呕。或胸中烦而不呕。或渴。或腹中痛。或胁下痞鞕。或心下悸。小便不利。或不渴。身有微热。或咳者。属$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019042,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '44、中风往来寒热。伤寒五六日以后。胸胁苦满。嘿嘿不欲饮食。烦心。喜呕。或胸中烦而不呕。或渴。或腹中痛。或胁下痞鞕。或心下悸。小便不利。或不渴。身有微热。或咳者。属$f{小柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jpH2WRafbbG', 4, '{"title":"第1019043条・辨可发汗病脉证并治第十六","description":"<p>45、伤寒四五日。身热恶风。颈项强。胁下满。手足温而渴者。属$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019043,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '45、伤寒四五日。身热恶风。颈项强。胁下满。手足温而渴者。属$f{小柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EFlToWObGW1', 4, '{"title":"第1019044条・辨可发汗病脉证并治第十六","description":"<p>46、伤寒六七日。发热微恶寒。支节烦疼。微呕。心下支结。外证未去者。$f{柴胡桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019044,"note":"","videoMemo":"","fangList":["柴胡桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '46、伤寒六七日。发热微恶寒。支节烦疼。微呕。心下支结。外证未去者。$f{柴胡桂枝汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ao63h7qhqMt', 4, '{"title":"第1019045条・辨可发汗病脉证并治第十六","description":"<p>47、少阴病。得之二三日。$f{麻黄附子甘草汤}。微发汗。以二三日无证。故微发汗也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019045,"note":"","videoMemo":"","fangList":["麻黄附子甘草汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '47、少阴病。得之二三日。$f{麻黄附子甘草汤}。微发汗。以二三日无证。故微发汗也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CQQcJb2b2UK', 4, '{"title":"第1019046条・辨可发汗病脉证并治第十六","description":"<p>48、脉浮。小便不利。微热消渴者。与$f{五苓散}利小便。发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019046,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '48、脉浮。小便不利。微热消渴者。与$f{五苓散}利小便。发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5gSqCp1kZAN', 4, '{"title":"第1020000条・辨发汗后病脉证并治第十七","description":"<p>1、二阳并病。太阳初得病时。发其汗。汗先出不彻。因转属阳明。续自微汗出。不恶寒。若太阳病证不罢者。不可下。下之为逆。如此可小发汗。设面色缘缘正赤者。阳气怫郁。在表当解之。熏之。若发汗不彻。不足言阳气怫郁。不得越。当汗不汗。其人烦躁。不知痛处。乍在腹中。乍在四肢。按之不可得。其人短气。但坐以汗出不彻故也。更发汗则愈。何以知汗出不彻。以脉涩故知也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、二阳并病。太阳初得病时。发其汗。汗先出不彻。因转属阳明。续自微汗出。不恶寒。若太阳病证不罢者。不可下。下之为逆。如此可小发汗。设面色缘缘正赤者。阳气怫郁。在表当解之。熏之。若发汗不彻。不足言阳气怫郁。不得越。当汗不汗。其人烦躁。不知痛处。乍在腹中。乍在四肢。按之不可得。其人短气。但坐以汗出不彻故也。更发汗则愈。何以知汗出不彻。以脉涩故知也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jmwIiDbzCCy', 4, '{"title":"第1020001条・辨发汗后病脉证并治第十七","description":"<p>2、未持脉时。病人叉手自冒心。师因教试令咳而不即咳者。此必两耳聋无闻也。所以然者。以重发汗虚。故如此。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、未持脉时。病人叉手自冒心。师因教试令咳而不即咳者。此必两耳聋无闻也。所以然者。以重发汗虚。故如此。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('owwKwu8C1Zi', 4, '{"title":"第1020002条・辨发汗后病脉证并治第十七","description":"<p>3、发汗后。饮水多必喘。以水灌之。亦喘。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、发汗后。饮水多必喘。以水灌之。亦喘。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NwVLObJb2AM', 4, '{"title":"第1020003条・辨发汗后病脉证并治第十七","description":"<p>4、发汗后。水药不得入口。为逆。若更发汗。必吐下不止。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、发汗后。水药不得入口。为逆。若更发汗。必吐下不止。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EFVKH3i23xU', 4, '{"title":"第1020004条・辨发汗后病脉证并治第十七","description":"<p>5、阳明病。本自汗出。医更重发汗。病已差。尚微烦不了了者。必大便鞕故也。以亡津液。胃中干燥。故令大便鞕。当问小便日几行。若本小便日三四行。今日再行。故知大便不久出。今为小便数少。以津液当还入胃中。故知不久必大便也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '5、阳明病。本自汗出。医更重发汗。病已差。尚微烦不了了者。必大便鞕故也。以亡津液。胃中干燥。故令大便鞕。当问小便日几行。若本小便日三四行。今日再行。故知大便不久出。今为小便数少。以津液当还入胃中。故知不久必大便也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RW6d5P9lTpd', 4, '{"title":"第1020005条・辨发汗后病脉证并治第十七","description":"<p>6、发汗多。若重发汗者。亡其阳。讝语。脉短者死。脉自和者。不死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、发汗多。若重发汗者。亡其阳。讝语。脉短者死。脉自和者。不死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pj4ZJWorLC7', 4, '{"title":"第1020006条・辨发汗后病脉证并治第十七","description":"<p>7、伤寒发汗已。身目为黄。所以然者。以寒湿$a{（一作温）}在里不解故也。以为不可下也。于寒湿中求之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、伤寒发汗已。身目为黄。所以然者。以寒湿$a{（一作温）}在里不解故也。以为不可下也。于寒湿中求之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pDfEWh4wtiN', 4, '{"title":"第1020007条・辨发汗后病脉证并治第十七","description":"<p>8、病人有寒。复发汗。胃中冷。必吐蚘。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '8、病人有寒。复发汗。胃中冷。必吐蚘。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F2gVoVWjyRu', 4, '{"title":"第1020008条・辨发汗后病脉证并治第十七","description":"<p>9、太阳病。发汗。遂漏不止。其人恶风。小便难。四肢微急。难以屈伸者。属$f{桂枝加附子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020008,"note":"","videoMemo":"","fangList":["桂枝加附子汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '9、太阳病。发汗。遂漏不止。其人恶风。小便难。四肢微急。难以屈伸者。属$f{桂枝加附子汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mdbDI6QI1Uf', 4, '{"title":"第1020009条・辨发汗后病脉证并治第十七","description":"<p>10、太阳病。初服$f{桂枝汤}。反烦不解者。先刺风池风府。却与$f{桂枝汤}。则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020009,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '10、太阳病。初服$f{桂枝汤}。反烦不解者。先刺风池风府。却与$f{桂枝汤}。则愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YrXgYyTZobt', 4, '{"title":"第1020010条・辨发汗后病脉证并治第十七","description":"<p>11、服$f{桂枝汤}。大汗出。脉洪大者。与$f{桂枝汤}。如前法。若形似疟。一日再发者。汗出必解。属$f{桂枝二麻黄一汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020010,"note":"","videoMemo":"","fangList":["桂枝汤","桂枝二麻黄一汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '11、服$f{桂枝汤}。大汗出。脉洪大者。与$f{桂枝汤}。如前法。若形似疟。一日再发者。汗出必解。属$f{桂枝二麻黄一汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sg3tKIevRF5', 4, '{"title":"第1020011条・辨发汗后病脉证并治第十七","description":"<p>12、服$f{桂枝汤}。大汗出后。大烦渴不解。脉洪大者。属$f{白虎加人参汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020011,"note":"","videoMemo":"","fangList":["桂枝汤","白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '12、服$f{桂枝汤}。大汗出后。大烦渴不解。脉洪大者。属$f{白虎加人参汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BYXcWDNchTw', 4, '{"title":"第1020012条・辨发汗后病脉证并治第十七","description":"<p>13、伤寒脉浮自汗出。小便数。心烦。微恶寒。脚挛急。反与桂枝。欲攻其表。此误也。得之便厥。咽中干。烦躁吐逆者。作$f{甘草干姜汤}与之。以复其阳。若厥愈足温者。更作$f{芍药甘草汤}与之。其脚即伸。若胃气不和。讝语者。少与$f{调胃承气汤}。若重发汗。复加烧针者。与$f{四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020012,"note":"","videoMemo":"","fangList":["甘草干姜汤","芍药甘草汤","调胃承气汤","四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '13、伤寒脉浮自汗出。小便数。心烦。微恶寒。脚挛急。反与桂枝。欲攻其表。此误也。得之便厥。咽中干。烦躁吐逆者。作$f{甘草干姜汤}与之。以复其阳。若厥愈足温者。更作$f{芍药甘草汤}与之。其脚即伸。若胃气不和。讝语者。少与$f{调胃承气汤}。若重发汗。复加烧针者。与$f{四逆汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Viulniedttb', 4, '{"title":"第1020013条・辨发汗后病脉证并治第十七","description":"<p>14、太阳病。脉浮紧。无汗。发热。身疼痛。八九日不解。表证仍在。此当复发汗。服汤已。微除。其人发烦目瞑剧者。必衄。衄乃解。所以然者。阳气重故也。宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020013,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '14、太阳病。脉浮紧。无汗。发热。身疼痛。八九日不解。表证仍在。此当复发汗。服汤已。微除。其人发烦目瞑剧者。必衄。衄乃解。所以然者。阳气重故也。宜$f{麻黄汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SqpfTj3OR3d', 4, '{"title":"第1020014条・辨发汗后病脉证并治第十七","description":"<p>15、伤寒发汗。已解半日许。复烦。脉浮数者。可更发汗。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020014,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '15、伤寒发汗。已解半日许。复烦。脉浮数者。可更发汗。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6BTL4ao4wU5', 4, '{"title":"第1020015条・辨发汗后病脉证并治第十七","description":"<p>16、发汗后。身疼痛。脉沉迟者。属桂枝加芍药生姜各一两人参三两$f{新加汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020015,"note":"","videoMemo":"","fangList":["新加汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '16、发汗后。身疼痛。脉沉迟者。属桂枝加芍药生姜各一两人参三两$f{新加汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mQqI353aua1', 4, '{"title":"第1020016条・辨发汗后病脉证并治第十七","description":"<p>17、发汗后不可更行$f{桂枝汤}。汗出而喘。无大热者。可与$f{麻黄杏仁甘草石膏汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020016,"note":"","videoMemo":"","fangList":["桂枝汤","麻黄杏仁甘草石膏汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '17、发汗后不可更行$f{桂枝汤}。汗出而喘。无大热者。可与$f{麻黄杏仁甘草石膏汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('APC4JZ0Em0z', 4, '{"title":"第1020017条・辨发汗后病脉证并治第十七","description":"<p>18、发汗过多。其人叉手自冒心。心下悸。欲得按者。属$f{桂枝甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020017,"note":"","videoMemo":"","fangList":["桂枝甘草汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '18、发汗过多。其人叉手自冒心。心下悸。欲得按者。属$f{桂枝甘草汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TCIkGoU5nF3', 4, '{"title":"第1020018条・辨发汗后病脉证并治第十七","description":"<p>19、发汗后。其人脐下悸者。欲作奔豚。属$f{茯苓桂枝甘草大枣汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020018,"note":"","videoMemo":"","fangList":["茯苓桂枝甘草大枣汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '19、发汗后。其人脐下悸者。欲作奔豚。属$f{茯苓桂枝甘草大枣汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r44TRoSKVeV', 4, '{"title":"第1020019条・辨发汗后病脉证并治第十七","description":"<p>20、发汗后。腹胀满者。属$f{厚朴生姜半夏甘草人参汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020019,"note":"","videoMemo":"","fangList":["厚朴生姜半夏甘草人参汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '20、发汗后。腹胀满者。属$f{厚朴生姜半夏甘草人参汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UWSuN88qH7C', 4, '{"title":"第1020020条・辨发汗后病脉证并治第十七","description":"<p>21、发汗病不解。反恶寒者。虚故也。属$f{芍药甘草附子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020020,"note":"","videoMemo":"","fangList":["芍药甘草附子汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '21、发汗病不解。反恶寒者。虚故也。属$f{芍药甘草附子汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AhPrliAtXLe', 4, '{"title":"第1020021条・辨发汗后病脉证并治第十七","description":"<p>22、发汗后恶寒者。虚故也。不恶寒。但热者。实也。当和胃气。属$f{调胃承气汤}。$a{（一法用$f{小承气汤}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020021,"note":"","videoMemo":"","fangList":["调胃承气汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '22、发汗后恶寒者。虚故也。不恶寒。但热者。实也。当和胃气。属$f{调胃承气汤}。$a{（一法用$f{小承气汤}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FKmHXhkIIXn', 4, '{"title":"第1020022条・辨发汗后病脉证并治第十七","description":"<p>23、太阳病。发汗后大汗出。胃中干。烦躁不得眠。欲得饮水者。少少与饮之。令胃气和则愈。若脉浮。小便不利。微热消渴者。属$f{五苓散}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020022,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '23、太阳病。发汗后大汗出。胃中干。烦躁不得眠。欲得饮水者。少少与饮之。令胃气和则愈。若脉浮。小便不利。微热消渴者。属$f{五苓散}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Wa5uSk396H', 4, '{"title":"第1020023条・辨发汗后病脉证并治第十七","description":"<p>24、发汗已。脉浮数烦渴者。属$f{五苓散}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020023,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '24、发汗已。脉浮数烦渴者。属$f{五苓散}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Uz1MYA2Both', 4, '{"title":"第1020024条・辨发汗后病脉证并治第十七","description":"<p>25、伤寒汗出而渴者。宜$f{五苓散}。不渴者。属$f{茯苓甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020024,"note":"","videoMemo":"","fangList":["五苓散","茯苓甘草汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '25、伤寒汗出而渴者。宜$f{五苓散}。不渴者。属$f{茯苓甘草汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aqn7wn5S5wD', 4, '{"title":"第1020025条・辨发汗后病脉证并治第十七","description":"<p>26、太阳病发汗。汗出不解。其人仍发热。心下悸。头眩身瞤动。振振欲擗$a{（一作僻）}地者。属$f{真武汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020025,"note":"","videoMemo":"","fangList":["真武汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '26、太阳病发汗。汗出不解。其人仍发热。心下悸。头眩身瞤动。振振欲擗$a{（一作僻）}地者。属$f{真武汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B2ohoWPrdaV', 4, '{"title":"第1020026条・辨发汗后病脉证并治第十七","description":"<p>27、伤寒汗出解之后。胃中不和。心下痞鞕。干噫食臭。胁下有水气。腹中雷鸣下利者。属$f{生姜泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020026,"note":"","videoMemo":"","fangList":["生姜泻心汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '27、伤寒汗出解之后。胃中不和。心下痞鞕。干噫食臭。胁下有水气。腹中雷鸣下利者。属$f{生姜泻心汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('083FgK4IUuy', 4, '{"title":"第1020027条・辨发汗后病脉证并治第十七","description":"<p>28、伤寒发热。汗出不解。心中痞鞕。呕吐而下利者。属$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020027,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '28、伤寒发热。汗出不解。心中痞鞕。呕吐而下利者。属$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oph9LtGQ8a3', 4, '{"title":"第1020028条・辨发汗后病脉证并治第十七","description":"<p>29、阳明病。自汗出若发汗。小便自利者。此为津液内竭。虽鞕不可攻之。须自欲大便。宜$f{蜜煎导}而通之。若土瓜根。及大猪胆汁。皆可为导。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020028,"note":"","videoMemo":"","fangList":["蜜煎导"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '29、阳明病。自汗出若发汗。小便自利者。此为津液内竭。虽鞕不可攻之。须自欲大便。宜$f{蜜煎导}而通之。若土瓜根。及大猪胆汁。皆可为导。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NIAi5jNw62Q', 4, '{"title":"第1020029条・辨发汗后病脉证并治第十七","description":"<p>30、太阳病。三日发汗不解。蒸蒸发热者。属胃也。属$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020029,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '30、太阳病。三日发汗不解。蒸蒸发热者。属胃也。属$f{调胃承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('01483GlTaiw', 4, '{"title":"第1020030条・辨发汗后病脉证并治第十七","description":"<p>31、大汗出。热不去。内拘急。四肢疼。又下利厥逆而恶寒者。属$f{四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020030,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '31、大汗出。热不去。内拘急。四肢疼。又下利厥逆而恶寒者。属$f{四逆汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KQH5b4rZNrX', 4, '{"title":"第1020031条・辨发汗后病脉证并治第十七","description":"<p>32、发汗后不解。腹满痛者。急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020031,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '32、发汗后不解。腹满痛者。急下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ikNMUOMtDpB', 4, '{"title":"第1020032条・辨发汗后病脉证并治第十七","description":"<p>33、发汗多。亡阳讝语者。不可下。与$f{柴胡桂枝汤}和其荣卫。以通津液。后自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1020032,"note":"","videoMemo":"","fangList":["柴胡桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '33、发汗多。亡阳讝语者。不可下。与$f{柴胡桂枝汤}和其荣卫。以通津液。后自愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '3RHMzkoFt6K');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lPJnkzHtgib', 4, '{"title":"第1021000条・辨不可吐第十八","description":"<p>1、太阳病。当恶寒发热。今自汗出。反不恶寒发热。关上脉细数者。以医吐之过也。若得病一二日吐之者。腹中饥。口不能食。三四日吐之者。不喜糜粥。欲食冷食。朝食暮吐。以医吐之所致也。此为小逆。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1021000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、太阳病。当恶寒发热。今自汗出。反不恶寒发热。关上脉细数者。以医吐之过也。若得病一二日吐之者。腹中饥。口不能食。三四日吐之者。不喜糜粥。欲食冷食。朝食暮吐。以医吐之所致也。此为小逆。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '8O28AfRA7i9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1EhP04K4rAs', 4, '{"title":"第1021001条・辨不可吐第十八","description":"<p>2、太阳病。吐之。但太阳病当恶寒。今反不恶寒。不欲近衣者。此为吐之。内烦也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1021001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、太阳病。吐之。但太阳病当恶寒。今反不恶寒。不欲近衣者。此为吐之。内烦也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '8O28AfRA7i9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TpexHFliCVf', 4, '{"title":"第1021002条・辨不可吐第十八","description":"<p>3、少阴病。饮食入口则吐。心中温温。欲吐复不能吐。始得之。手足寒。脉弦迟者。此胸中实。不可下也。若膈上有寒饮干呕者。不可吐也。当温之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1021002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、少阴病。饮食入口则吐。心中温温。欲吐复不能吐。始得之。手足寒。脉弦迟者。此胸中实。不可下也。若膈上有寒饮干呕者。不可吐也。当温之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '8O28AfRA7i9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iW1O6rRDOGD', 4, '{"title":"第1021003条・辨不可吐第十八","description":"<p>4、诸四逆厥者。不可吐之。虚家亦然。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1021003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、诸四逆厥者。不可吐之。虚家亦然。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '8O28AfRA7i9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A702N5ToQ6I', 4, '{"title":"第1022000条・辨可吐第十九","description":"<p>1、大法。春宜吐。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、大法。春宜吐。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CM793Gr8STH', 4, '{"title":"第1022001条・辨可吐第十九","description":"<p>2、凡用吐汤。中病便止。不必尽剂也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、凡用吐汤。中病便止。不必尽剂也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1mt91frI0q5', 4, '{"title":"第1022002条・辨可吐第十九","description":"<p>3、病如桂枝证。头不痛。项不强。寸脉微浮。胸中痞鞕。气上撞咽喉。不得息者。此为有寒。当吐之。$a{（一云此以内有久痰。宜吐之。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、病如桂枝证。头不痛。项不强。寸脉微浮。胸中痞鞕。气上撞咽喉。不得息者。此为有寒。当吐之。$a{（一云此以内有久痰。宜吐之。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MOfnbd4x6G2', 4, '{"title":"第1022003条・辨可吐第十九","description":"<p>4、病胸上诸实。$a{（一作寒。）}胸中郁郁而痛。不能食。欲使人按之。而反有涎唾。下利日十余行。其脉反迟。寸口脉微滑。此可吐之。吐之。利则止。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、病胸上诸实。$a{（一作寒。）}胸中郁郁而痛。不能食。欲使人按之。而反有涎唾。下利日十余行。其脉反迟。寸口脉微滑。此可吐之。吐之。利则止。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z1MJkBsXVlh', 4, '{"title":"第1022004条・辨可吐第十九","description":"<p>5、少阴病。饮食入口则吐。心中温温。欲吐复不能吐者。宜吐之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '5、少阴病。饮食入口则吐。心中温温。欲吐复不能吐者。宜吐之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qwnHEIn4KD0', 4, '{"title":"第1022005条・辨可吐第十九","description":"<p>6、宿食在上管者。当吐之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、宿食在上管者。当吐之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mFHbxqgMFw7', 4, '{"title":"第1022006条・辨可吐第十九","description":"<p>7、病手足逆冷。脉乍结。以客气在胸中。心下满而烦。欲食不能食者。病在胸中。当吐之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1022006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、病手足逆冷。脉乍结。以客气在胸中。心下满而烦。欲食不能食者。病在胸中。当吐之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'hS8ABOXG3VJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NieFSPJRC9r', 4, '{"title":"第1023000条・辨不可下病脉证并治第二十","description":"<p>1、脉濡而弱。弱反在关。濡反在巅。微反在上。涩反在下。微则阳气不足。涩则无血。阳气反微。中风汗出而反躁烦。涩则无血。厥而且寒。阳微则不可下。下之则心下痞鞕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、脉濡而弱。弱反在关。濡反在巅。微反在上。涩反在下。微则阳气不足。涩则无血。阳气反微。中风汗出而反躁烦。涩则无血。厥而且寒。阳微则不可下。下之则心下痞鞕。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6rTNPlLKVg3', 4, '{"title":"第1023001条・辨不可下病脉证并治第二十","description":"<p>2、动气在右。不可下。下之则津液内竭。咽燥鼻干。头眩心悸也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、动气在右。不可下。下之则津液内竭。咽燥鼻干。头眩心悸也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y5rgvOUK4AN', 4, '{"title":"第1023002条・辨不可下病脉证并治第二十","description":"<p>3、动气在左。不可下。下之则腹内拘急。食不下。动气更剧。虽有身热。卧则欲踡。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、动气在左。不可下。下之则腹内拘急。食不下。动气更剧。虽有身热。卧则欲踡。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZtfqDBlz2BM', 4, '{"title":"第1023003条・辨不可下病脉证并治第二十","description":"<p>4、动气在上。不可下。下之。则掌握热烦。身上浮冷。热汗自泄。欲得水自灌。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、动气在上。不可下。下之。则掌握热烦。身上浮冷。热汗自泄。欲得水自灌。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hydqfk5369g', 4, '{"title":"第1023004条・辨不可下病脉证并治第二十","description":"<p>5、动气在下。不可下。下之。则腹胀满。卒起头眩。食则下清谷。心下痞也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '5、动气在下。不可下。下之。则腹胀满。卒起头眩。食则下清谷。心下痞也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QoDit3Z1PAc', 4, '{"title":"第1023005条・辨不可下病脉证并治第二十","description":"<p>6、咽中闭寒。不可下。下之。则上轻下重。水浆不下。卧则欲踡。身急痛。下利日数十行。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、咽中闭寒。不可下。下之。则上轻下重。水浆不下。卧则欲踡。身急痛。下利日数十行。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JiNh6287MwL', 4, '{"title":"第1023006条・辨不可下病脉证并治第二十","description":"<p>7、诸外实者。不可下。下之则发微热。亡脉。厥者。当齐握热。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、诸外实者。不可下。下之则发微热。亡脉。厥者。当齐握热。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rmI5ut1g4CE', 4, '{"title":"第1023007条・辨不可下病脉证并治第二十","description":"<p>8、诸虚者。不可下。下之则大渴。求水者易愈。恶水者剧。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '8、诸虚者。不可下。下之则大渴。求水者易愈。恶水者剧。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mwLWm29xn3Y', 4, '{"title":"第1023008条・辨不可下病脉证并治第二十","description":"<p>9、脉濡而弱。弱反在关。濡反在巅。弦反在上。微反在下。弦为阳运。微为阴寒。上实下虚。意欲得温。微弦为虚。虚者不可下也。微则为咳。咳则吐涎。下之。则咳止而利因不休。利不休。则胸中如虫啮。粥入则出。小便不利。两胁拘急。喘息为难。颈背相引。臂则不仁。极寒反汗出。身冷若冰。眼睛不慧。语言不休。而谷气多入。此为除中$a{（亦云消中。）}口虽欲言。舌不得前。方达</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '9、脉濡而弱。弱反在关。濡反在巅。弦反在上。微反在下。弦为阳运。微为阴寒。上实下虚。意欲得温。微弦为虚。虚者不可下也。微则为咳。咳则吐涎。下之。则咳止而利因不休。利不休。则胸中如虫啮。粥入则出。小便不利。两胁拘急。喘息为难。颈背相引。臂则不仁。极寒反汗出。身冷若冰。眼睛不慧。语言不休。而谷气多入。此为除中$a{（亦云消中。）}口虽欲言。舌不得前。方达', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cbNmCeLF6ZW', 4, '{"title":"第1023009条・辨不可下病脉证并治第二十","description":"<p>10、脉濡而弱。弱反在关。濡反在巅。浮反在上。数反在下。浮为阳虚。数为无血。浮为虚。数生热。浮为虚。自汗出而恶寒。数为痛。振而寒慄。微弱在关。胸下为急。喘汗而不得呼吸。呼吸之中。痛在于胁。振寒相搏。形如疟状。医反下之。故令脉数发热。狂走见鬼。心下为痞。小便淋漓。小腹甚鞕。小便则尿血也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '10、脉濡而弱。弱反在关。濡反在巅。浮反在上。数反在下。浮为阳虚。数为无血。浮为虚。数生热。浮为虚。自汗出而恶寒。数为痛。振而寒慄。微弱在关。胸下为急。喘汗而不得呼吸。呼吸之中。痛在于胁。振寒相搏。形如疟状。医反下之。故令脉数发热。狂走见鬼。心下为痞。小便淋漓。小腹甚鞕。小便则尿血也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ltMpCmK2XKK', 4, '{"title":"第1023010条・辨不可下病脉证并治第二十","description":"<p>11、脉濡而紧。濡则卫气微。紧则荣中寒。阳微卫中风。发热而恶寒。荣紧胃气冷。微呕心内烦。医谓有大热。解肌而发汗。亡阳虚烦躁。心下苦痞坚。表里俱虚竭。卒起而头眩。客热在皮肤。怅怏不得眠。不知胃气冷。紧。寒在关元。技巧无所施。汲水灌其身。客热应时罢。慄慄而振寒。重被而覆之。汗出而冒巅。体惕而又振。小便为微难。寒气因水发。清谷不容间。呕变反肠出。颠倒不得安。手足为微逆。身冷而内烦。迟欲从后救。安可复追还。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '11、脉濡而紧。濡则卫气微。紧则荣中寒。阳微卫中风。发热而恶寒。荣紧胃气冷。微呕心内烦。医谓有大热。解肌而发汗。亡阳虚烦躁。心下苦痞坚。表里俱虚竭。卒起而头眩。客热在皮肤。怅怏不得眠。不知胃气冷。紧。寒在关元。技巧无所施。汲水灌其身。客热应时罢。慄慄而振寒。重被而覆之。汗出而冒巅。体惕而又振。小便为微难。寒气因水发。清谷不容间。呕变反肠出。颠倒不得安。手足为微逆。身冷而内烦。迟欲从后救。安可复追还。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V72haZGARTS', 4, '{"title":"第1023011条・辨不可下病脉证并治第二十","description":"<p>12、脉浮而大。浮为气实。大为血虚。血虚为无阴。孤阳独下阴部者。小便当赤而难。胞中当虚。今反小便利而大汗出。法应卫家当微。今反更实。津液四射荣竭血尽。干烦而不得眠。血薄肉消而成暴$a{（一云黑）}液。医复以毒药攻其胃。此为重虚。客阳去有期。必下如污泥而死。方达</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '12、脉浮而大。浮为气实。大为血虚。血虚为无阴。孤阳独下阴部者。小便当赤而难。胞中当虚。今反小便利而大汗出。法应卫家当微。今反更实。津液四射荣竭血尽。干烦而不得眠。血薄肉消而成暴$a{（一云黑）}液。医复以毒药攻其胃。此为重虚。客阳去有期。必下如污泥而死。方达', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZUyXAAF8ywa', 4, '{"title":"第1023012条・辨不可下病脉证并治第二十","description":"<p>13、脉浮而紧。浮则为风。紧则为寒。风则伤卫。寒则伤荣。荣卫俱病。骨节烦疼。当发其汗。而不可下也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '13、脉浮而紧。浮则为风。紧则为寒。风则伤卫。寒则伤荣。荣卫俱病。骨节烦疼。当发其汗。而不可下也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wiNNRjr50oP', 4, '{"title":"第1023013条・辨不可下病脉证并治第二十","description":"<p>14、趺阳脉迟而缓。胃气如经也。趺阳脉浮而数。浮则伤胃。数则动脾。此非本病。医特下之所为也。荣卫内陷。其数先微。脉反但浮。其人必大便鞕。气噫而除。何以言之。本以数脉动脾。其数先微。故知脾气不治。大便鞕。气噫而除。今脉反浮。其数改微。邪气。独留。心中则饥。邪热不杀谷。潮热发渴。数脉当迟缓。脉因前后度数如法。病者则饥。数脉不时。则生恶疮也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '14、趺阳脉迟而缓。胃气如经也。趺阳脉浮而数。浮则伤胃。数则动脾。此非本病。医特下之所为也。荣卫内陷。其数先微。脉反但浮。其人必大便鞕。气噫而除。何以言之。本以数脉动脾。其数先微。故知脾气不治。大便鞕。气噫而除。今脉反浮。其数改微。邪气。独留。心中则饥。邪热不杀谷。潮热发渴。数脉当迟缓。脉因前后度数如法。病者则饥。数脉不时。则生恶疮也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kRZeVH8Q5gX', 4, '{"title":"第1023014条・辨不可下病脉证并治第二十","description":"<p>15、脉数者。久数不止。止则邪结。正气不能复。正气却结于藏。故邪气浮之。与皮毛相得。脉数者不可下。下之必烦。利不止。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '15、脉数者。久数不止。止则邪结。正气不能复。正气却结于藏。故邪气浮之。与皮毛相得。脉数者不可下。下之必烦。利不止。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Abwu92w8jyi', 4, '{"title":"第1023015条・辨不可下病脉证并治第二十","description":"<p>16、少阴病。脉微。不可发汗。亡阳故也。阳已虚。尺脉弱涩者。复不可下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '16、少阴病。脉微。不可发汗。亡阳故也。阳已虚。尺脉弱涩者。复不可下之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n50NvDK0yFS', 4, '{"title":"第1023016条・辨不可下病脉证并治第二十","description":"<p>17、脉浮大。应发汗。医反下之。此为大逆也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '17、脉浮大。应发汗。医反下之。此为大逆也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zDgYXVdlB2V', 4, '{"title":"第1023017条・辨不可下病脉证并治第二十","description":"<p>18、脉浮而大。心下反鞕。有热。属藏者。攻之不令发汗。属府者。不令溲数。溲数则大便鞕。汗多则热愈。汗少则便难。脉迟尚未可攻。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '18、脉浮而大。心下反鞕。有热。属藏者。攻之不令发汗。属府者。不令溲数。溲数则大便鞕。汗多则热愈。汗少则便难。脉迟尚未可攻。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X5b6BTMf0Cz', 4, '{"title":"第1023018条・辨不可下病脉证并治第二十","description":"<p>19、二阳并病。太阳初得病时。而发其汗。汗先出不彻。因转属阳明。续自微汗出不恶寒。若太阳证不罢者。不可下。下之为逆。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '19、二阳并病。太阳初得病时。而发其汗。汗先出不彻。因转属阳明。续自微汗出不恶寒。若太阳证不罢者。不可下。下之为逆。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4BKAvaFXGhE', 4, '{"title":"第1023019条・辨不可下病脉证并治第二十","description":"<p>20、结胸证。脉浮大者。不可下。下之即死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '20、结胸证。脉浮大者。不可下。下之即死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q4LmUfsf5Xo', 4, '{"title":"第1023020条・辨不可下病脉证并治第二十","description":"<p>21、太阳与阳明合病。喘而胸满者。不可下。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '21、太阳与阳明合病。喘而胸满者。不可下。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g21tfYTJu8f', 4, '{"title":"第1023021条・辨不可下病脉证并治第二十","description":"<p>22、太阳与少阳合病者。心下鞕。颈项强而眩者。不可下。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '22、太阳与少阳合病者。心下鞕。颈项强而眩者。不可下。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cVrQG9sWejD', 4, '{"title":"第1023022条・辨不可下病脉证并治第二十","description":"<p>23、诸四逆厥者。不可下之。虚家亦然。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '23、诸四逆厥者。不可下之。虚家亦然。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yZJjfqzWnJ8', 4, '{"title":"第1023023条・辨不可下病脉证并治第二十","description":"<p>24、病欲吐者。不可下。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '24、病欲吐者。不可下。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YTPexILLgzR', 4, '{"title":"第1023024条・辨不可下病脉证并治第二十","description":"<p>25、太阳病有外证。未解。不可下。下之为逆。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '25、太阳病有外证。未解。不可下。下之为逆。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kSPYvoMqATb', 4, '{"title":"第1023025条・辨不可下病脉证并治第二十","description":"<p>26、病发于阳而反下之。热入因作结胸。病发于阴。而反下之。因作痞。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '26、病发于阳而反下之。热入因作结胸。病发于阴。而反下之。因作痞。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YCtDNX8s27Q', 4, '{"title":"第1023026条・辨不可下病脉证并治第二十","description":"<p>27、病脉浮而紧。而复下之。紧反入里。则作痞。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '27、病脉浮而紧。而复下之。紧反入里。则作痞。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TEDgVW37nvB', 4, '{"title":"第1023027条・辨不可下病脉证并治第二十","description":"<p>28、夫病阳多者热。下之则鞕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '28、夫病阳多者热。下之则鞕。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2dOYkj96leC', 4, '{"title":"第1023028条・辨不可下病脉证并治第二十","description":"<p>29、本虚。攻其热。必哕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '29、本虚。攻其热。必哕。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7vZv0h3ECB4', 4, '{"title":"第1023029条・辨不可下病脉证并治第二十","description":"<p>30、无阳阴强。大便鞕者。下之必清谷腹满。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '30、无阳阴强。大便鞕者。下之必清谷腹满。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d7IT1IInzee', 4, '{"title":"第1023030条・辨不可下病脉证并治第二十","description":"<p>31、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。下之必胸下结鞕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '31、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。下之必胸下结鞕。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2RNa665MI2U', 4, '{"title":"第1023031条・辨不可下病脉证并治第二十","description":"<p>32、厥阴之为病。消渴。气上撞心。心中疼热。饥而不欲食。食则吐蚘。下之。利不止。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '32、厥阴之为病。消渴。气上撞心。心中疼热。饥而不欲食。食则吐蚘。下之。利不止。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c8ffro7k6SO', 4, '{"title":"第1023032条・辨不可下病脉证并治第二十","description":"<p>33、少阴病。饮食入口则吐。心中温温。欲吐复不能吐始得之。手足寒。脉弦迟者。此胸中实不可下也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023032,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '33、少阴病。饮食入口则吐。心中温温。欲吐复不能吐始得之。手足寒。脉弦迟者。此胸中实不可下也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hx38MB1pze6', 4, '{"title":"第1023033条・辨不可下病脉证并治第二十","description":"<p>34、伤寒五六日。不结胸。腹濡。脉虚。复厥者。不可下。此亡血。下之死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '34、伤寒五六日。不结胸。腹濡。脉虚。复厥者。不可下。此亡血。下之死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q3JUft89HFi', 4, '{"title":"第1023034条・辨不可下病脉证并治第二十","description":"<p>35、伤寒发热。头痛。微汗出。发汗则不识人。熏之则喘。不得小便。心腹满。下之则短气。小便难。头痛背强加温针。则衄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '35、伤寒发热。头痛。微汗出。发汗则不识人。熏之则喘。不得小便。心腹满。下之则短气。小便难。头痛背强加温针。则衄。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('42AGNEdc8lB', 4, '{"title":"第1023035条・辨不可下病脉证并治第二十","description":"<p>36、伤寒脉阴阳俱紧。恶寒发热。则脉欲厥。厥者。脉初来大。渐渐小。更来渐大。是其候也。如此者。恶寒。甚者翕翕汗出。喉中痛。若热多者。目赤脉多。睛不慧。医复发之。咽中则伤。若复下之。则两目闭。寒多。便清谷。热多。便脓血。若熏之。则身发黄。若熨之。则咽燥。若小便利者。可救之。若小便难者。为危殆。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023035,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '36、伤寒脉阴阳俱紧。恶寒发热。则脉欲厥。厥者。脉初来大。渐渐小。更来渐大。是其候也。如此者。恶寒。甚者翕翕汗出。喉中痛。若热多者。目赤脉多。睛不慧。医复发之。咽中则伤。若复下之。则两目闭。寒多。便清谷。热多。便脓血。若熏之。则身发黄。若熨之。则咽燥。若小便利者。可救之。若小便难者。为危殆。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GiJ9wB1OAGq', 4, '{"title":"第1023036条・辨不可下病脉证并治第二十","description":"<p>37、伤寒发热。口中勃勃气出。头痛目黄。衄不可制。贪水者必呕。恶水者厥。若下之。咽中生疮。假令手足温者。必下重。便脓血。头痛目黄者。若下之。则目闭。贪水者。若下之。其脉必厥。其声嘤。咽喉塞。若发汗。则战慄。阴阳俱虚。恶水者。若下之。则里冷。不嗜食大便完谷出。若发汗。则口中伤。舌上白胎。烦躁。脉数实。不大便六七日。后必便血。若发汗。则小便自利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '37、伤寒发热。口中勃勃气出。头痛目黄。衄不可制。贪水者必呕。恶水者厥。若下之。咽中生疮。假令手足温者。必下重。便脓血。头痛目黄者。若下之。则目闭。贪水者。若下之。其脉必厥。其声嘤。咽喉塞。若发汗。则战慄。阴阳俱虚。恶水者。若下之。则里冷。不嗜食大便完谷出。若发汗。则口中伤。舌上白胎。烦躁。脉数实。不大便六七日。后必便血。若发汗。则小便自利也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6SPH9h7wcgm', 4, '{"title":"第1023037条・辨不可下病脉证并治第二十","description":"<p>38、得病二三日。脉弱。无太阳柴胡证。烦躁。心下痞。至四日。虽能食。以承气汤少少与微和之。令小安。至六日。与承气汤一升。若不大便。六七日。小便少。虽不大便。但头鞭。後必溏。未定成鞭。攻之必溏。须小便利。屎定鞭。乃可攻之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '38、得病二三日。脉弱。无太阳柴胡证。烦躁。心下痞。至四日。虽能食。以承气汤少少与微和之。令小安。至六日。与承气汤一升。若不大便。六七日。小便少。虽不大便。但头鞭。後必溏。未定成鞭。攻之必溏。须小便利。屎定鞭。乃可攻之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('04ahY24zujG', 4, '{"title":"第1023038条・辨不可下病脉证并治第二十","description":"<p>39、藏结无阳证。不往来寒热。其人反静。舌上苔滑者。不可攻也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '39、藏结无阳证。不往来寒热。其人反静。舌上苔滑者。不可攻也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YON5KI6rRVy', 4, '{"title":"第1023039条・辨不可下病脉证并治第二十","description":"<p>40、伤寒呕多。虽有阳明证。不可攻之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023039,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '40、伤寒呕多。虽有阳明证。不可攻之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bBtAUjXASLX', 4, '{"title":"第1023040条・辨不可下病脉证并治第二十","description":"<p>41、阳明病。潮热。大便微鞕者。可与$f{大承气汤}。不鞕者。不可与之。若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转失气者此有燥屎也。乃可攻之。若不转失气者。此但初头鞕。后必溏。不可攻之。攻之必胀满。不能食也。欲饮水者。与水则哕。其后发热者。大便必复鞕而少也。以$f{小承气汤}和之。不转失气者。慎不可攻也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023040,"note":"","videoMemo":"","fangList":["大承气汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '41、阳明病。潮热。大便微鞕者。可与$f{大承气汤}。不鞕者。不可与之。若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转失气者此有燥屎也。乃可攻之。若不转失气者。此但初头鞕。后必溏。不可攻之。攻之必胀满。不能食也。欲饮水者。与水则哕。其后发热者。大便必复鞕而少也。以$f{小承气汤}和之。不转失气者。慎不可攻也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xYU40eILkVF', 4, '{"title":"第1023041条・辨不可下病脉证并治第二十","description":"<p>42、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞鞕而满。干呕。心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。此非结热。但以胃中虚。客气上逆。故使鞕也。属$f{甘草泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023041,"note":"","videoMemo":"","fangList":["甘草泻心汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '42、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞鞕而满。干呕。心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。此非结热。但以胃中虚。客气上逆。故使鞕也。属$f{甘草泻心汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wkuRMrITfDi', 4, '{"title":"第1023042条・辨不可下病脉证并治第二十","description":"<p>43、下利脉大者。虚也。以强下之故也。设脉浮革。因尔肠鸣者。属$f{当归四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023042,"note":"","videoMemo":"","fangList":["当归四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '43、下利脉大者。虚也。以强下之故也。设脉浮革。因尔肠鸣者。属$f{当归四逆汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P53aa7GF6Pj', 4, '{"title":"第1023043条・辨不可下病脉证并治第二十","description":"<p>44、阳明病。身合色赤。不可攻之。必发热色黄者。小便不利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023043,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '44、阳明病。身合色赤。不可攻之。必发热色黄者。小便不利也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wva6s2RO8GR', 4, '{"title":"第1023044条・辨不可下病脉证并治第二十","description":"<p>45、阳明病。心下鞕满者。不可攻之。攻之。利遂不止者。死。利止者。愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023044,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '45、阳明病。心下鞕满者。不可攻之。攻之。利遂不止者。死。利止者。愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aILBY5ZgT7c', 4, '{"title":"第1023045条・辨不可下病脉证并治第二十","description":"<p>46、阳明病。自汗出。若发汗。小便自利者。此为津液内竭。虽鞕。不可攻之。须自欲大便。宜$f{蜜煎导}而通之。若土瓜根。及猪胆汁。皆可为导。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1023045,"note":"","videoMemo":"","fangList":["蜜煎导"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '46、阳明病。自汗出。若发汗。小便自利者。此为津液内竭。虽鞕。不可攻之。须自欲大便。宜$f{蜜煎导}而通之。若土瓜根。及猪胆汁。皆可为导。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'er4x5nhDnTC');
