INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8mf3SGcSnTG', 4, '{"title":"第1024005条・辨可下病脉证并治第二十一","description":"<p>6、少阴病。下利清水。色纯青。心下必痛。口干燥者。可下之。宜大柴胡$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024005,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、少阴病。下利清水。色纯青。心下必痛。口干燥者。可下之。宜大柴胡$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yJScme2PlkA', 4, '{"title":"第1024006条・辨可下病脉证并治第二十一","description":"<p>7、下利。三部脉皆平。按之心下鞕者。急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024006,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、下利。三部脉皆平。按之心下鞕者。急下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iaTfUwUwVrQ', 4, '{"title":"第1024007条・辨可下病脉证并治第二十一","description":"<p>8、下利。脉迟而滑者。内实也。利未欲止。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024007,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '8、下利。脉迟而滑者。内实也。利未欲止。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VrGW0miOYcm', 4, '{"title":"第1024008条・辨可下病脉证并治第二十一","description":"<p>9、阳明少阳合病。必下利。其脉不负者。为顺也。负者。失也。互相克贼。名为负也。脉滑而数者。有宿食。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024008,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '9、阳明少阳合病。必下利。其脉不负者。为顺也。负者。失也。互相克贼。名为负也。脉滑而数者。有宿食。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ubtMcCRLjkb', 4, '{"title":"第1024009条・辨可下病脉证并治第二十一","description":"<p>10、问曰。人病有宿食。何以别之。师曰。寸口脉浮而大。按之反涩。尺中亦微而涩。故知有宿食。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024009,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '10、问曰。人病有宿食。何以别之。师曰。寸口脉浮而大。按之反涩。尺中亦微而涩。故知有宿食。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aS7k9CG1l8C', 4, '{"title":"第1024010条・辨可下病脉证并治第二十一","description":"<p>11、下利不欲食者。以有宿食故也。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024010,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '11、下利不欲食者。以有宿食故也。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
