INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZkAaIut2HHp', 4, '{"title":"第1024014条・辨可下病脉证并治第二十一","description":"<p>15、腹满不减。减不足言。当下之。宜大柴胡。$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024014,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '15、腹满不减。减不足言。当下之。宜大柴胡。$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Pa2HApB6TG', 4, '{"title":"第1024015条・辨可下病脉证并治第二十一","description":"<p>16、伤寒后脉沉。沉者。内实也。下之解。宜$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024015,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '16、伤寒后脉沉。沉者。内实也。下之解。宜$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LjbzpYJL9fC', 4, '{"title":"第1024016条・辨可下病脉证并治第二十一","description":"<p>17、伤寒六七日。目中不了了。睛不和。无表里证。大便难。身微热者。此为实也。急下之。宜大承气$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024016,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '17、伤寒六七日。目中不了了。睛不和。无表里证。大便难。身微热者。此为实也。急下之。宜大承气$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wwEV5Pl77DX', 4, '{"title":"第1024017条・辨可下病脉证并治第二十一","description":"<p>18、太阳病。未解。脉阴阳俱停。$a{（一作微）}必先振慄汗出而解。但阴脉微$a{（一作尺脉实）}者。下之而解。宜$f{大柴胡汤}。$a{（一法用$f{调胃承气汤}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024017,"note":"","videoMemo":"","fangList":["大柴胡汤","调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '18、太阳病。未解。脉阴阳俱停。$a{（一作微）}必先振慄汗出而解。但阴脉微$a{（一作尺脉实）}者。下之而解。宜$f{大柴胡汤}。$a{（一法用$f{调胃承气汤}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dq4ZycvdvaW', 4, '{"title":"第1024018条・辨可下病脉证并治第二十一","description":"<p>19、脉双弦而迟者。必心下鞕。脉大而紧者。阳中有阴也。可下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024018,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '19、脉双弦而迟者。必心下鞕。脉大而紧者。阳中有阴也。可下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WMwKT67DAgH', 4, '{"title":"第1024019条・辨可下病脉证并治第二十一","description":"<p>20、结胸者。项亦强。如柔痓状。下之则和。$a{（结胸门用$f{大陷胸丸}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024019,"note":"","videoMemo":"","fangList":["大陷胸丸"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '20、结胸者。项亦强。如柔痓状。下之则和。$a{（结胸门用$f{大陷胸丸}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5oQ1tjpr5DK', 4, '{"title":"第1024020条・辨可下病脉证并治第二十一","description":"<p>21、病人无表里证。发热七八日。虽脉浮数者。可下之。宜$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024020,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '21、病人无表里证。发热七八日。虽脉浮数者。可下之。宜$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e5D3ede2846', 4, '{"title":"第1024021条・辨可下病脉证并治第二十一","description":"<p>22、太阳病。六七日表证仍在。脉微而沉。反不结胸。其人发狂者。以热在下焦。少腹当鞕满。而小便自利者。下血乃愈。所以然者。以太阳随经。瘀热在里故也。宜下之以$f{抵当汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024021,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '22、太阳病。六七日表证仍在。脉微而沉。反不结胸。其人发狂者。以热在下焦。少腹当鞕满。而小便自利者。下血乃愈。所以然者。以太阳随经。瘀热在里故也。宜下之以$f{抵当汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ukf8J8CAS3Q', 4, '{"title":"第1024022条・辨可下病脉证并治第二十一","description":"<p>23、太阳病。身黄。脉沉结。少腹鞕满。小便不利者。为无血也。小便自利。其人如狂者。血证谛。属$f{抵当汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024022,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '23、太阳病。身黄。脉沉结。少腹鞕满。小便不利者。为无血也。小便自利。其人如狂者。血证谛。属$f{抵当汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QNerXkFwBgt', 4, '{"title":"第1024023条・辨可下病脉证并治第二十一","description":"<p>24、伤寒有热。少腹满。应小便不利。今反利者。为有血也。当下之。宜$f{抵当丸}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024023,"note":"","videoMemo":"","fangList":["抵当丸"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '24、伤寒有热。少腹满。应小便不利。今反利者。为有血也。当下之。宜$f{抵当丸}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dD2iPYUWXvU', 4, '{"title":"第1024024条・辨可下病脉证并治第二十一","description":"<p>25、阳明病。发热汗出者。此为热越。不能发黄也。但头汗出。身无汗。剂颈而还。小便不利。渴引水浆者。以瘀热在里。身必发黄。宜下之以$f{茵陈蒿汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024024,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '25、阳明病。发热汗出者。此为热越。不能发黄也。但头汗出。身无汗。剂颈而还。小便不利。渴引水浆者。以瘀热在里。身必发黄。宜下之以$f{茵陈蒿汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EtrdDCEdoJ8', 4, '{"title":"第1024025条・辨可下病脉证并治第二十一","description":"<p>26、阳明证。其人喜忘者。必有畜血。所以然者。本有久瘀血。故令喜忘。屎虽鞕。大便反易。其色必黑。宜$f{抵当汤}下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024025,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '26、阳明证。其人喜忘者。必有畜血。所以然者。本有久瘀血。故令喜忘。屎虽鞕。大便反易。其色必黑。宜$f{抵当汤}下之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RdWnLLBsXq8', 4, '{"title":"第1024026条・辨可下病脉证并治第二十一","description":"<p>27、汗$a{（一作卧）}出讝语者。以有燥屎在胃中。此为风也。须下者。过经乃可下之。下之若早者。语言必乱。以表虚里实故也。下之愈。宜大柴胡$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024026,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '27、汗$a{（一作卧）}出讝语者。以有燥屎在胃中。此为风也。须下者。过经乃可下之。下之若早者。语言必乱。以表虚里实故也。下之愈。宜大柴胡$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I52KU82TNp8', 4, '{"title":"第1024027条・辨可下病脉证并治第二十一","description":"<p>28、病人烦热汗出则解。又如疟状。日晡所发热者。属阳明也。脉实者。可下之。宜大柴胡$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024027,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '28、病人烦热汗出则解。又如疟状。日晡所发热者。属阳明也。脉实者。可下之。宜大柴胡$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0IW6b7AHk06', 4, '{"title":"第1024028条・辨可下病脉证并治第二十一","description":"<p>29、阳明病。讝语。有潮热。反不能食者。胃中有燥屎五六枚也。若能食者。但鞕耳。属$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024028,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '29、阳明病。讝语。有潮热。反不能食者。胃中有燥屎五六枚也。若能食者。但鞕耳。属$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G4AU6wtgC78', 4, '{"title":"第1024029条・辨可下病脉证并治第二十一","description":"<p>30、下利讝语者。有燥屎也。属$f{小承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024029,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '30、下利讝语者。有燥屎也。属$f{小承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kG17yUnR7Px', 4, '{"title":"第1024030条・辨可下病脉证并治第二十一","description":"<p>31、得病二三日。脉弱。无太阳柴胡证。烦躁。心下痞。至四五日。虽能食。以承气汤少少与微和之。令小安。至六日。与承气汤一升。若不大便六七日。小便少者。虽不大便。但初头鞕。后必溏。此未定成鞕也。攻之必溏。须小便利。屎定鞕。乃可攻之。宜$f{大承气汤}。$a{（一云$f{大柴胡汤}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024030,"note":"","videoMemo":"","fangList":["大承气汤","大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '31、得病二三日。脉弱。无太阳柴胡证。烦躁。心下痞。至四五日。虽能食。以承气汤少少与微和之。令小安。至六日。与承气汤一升。若不大便六七日。小便少者。虽不大便。但初头鞕。后必溏。此未定成鞕也。攻之必溏。须小便利。屎定鞕。乃可攻之。宜$f{大承气汤}。$a{（一云$f{大柴胡汤}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('obat4WSMbmK', 4, '{"title":"第1024031条・辨可下病脉证并治第二十一","description":"<p>32、太阳病中风。下利。呕逆。表解者。乃可攻之。其人漐漐汗出。发作有时。头痛。心下痞鞕。满引。胁下痛。干呕则短气。汗出不恶寒者。此表解里未和也。属$f{十枣汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024031,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '32、太阳病中风。下利。呕逆。表解者。乃可攻之。其人漐漐汗出。发作有时。头痛。心下痞鞕。满引。胁下痛。干呕则短气。汗出不恶寒者。此表解里未和也。属$f{十枣汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mi75iAaBE6I', 4, '{"title":"第1024032条・辨可下病脉证并治第二十一","description":"<p>33、太阳病不解。热结膀胱。其人如狂。血自下。下者愈。其外未解者。尚未可攻。当先解其外。外解已。但少腹急结者。乃可攻之。宜$f{桃核承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024032,"note":"","videoMemo":"","fangList":["桃核承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '33、太阳病不解。热结膀胱。其人如狂。血自下。下者愈。其外未解者。尚未可攻。当先解其外。外解已。但少腹急结者。乃可攻之。宜$f{桃核承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O7OKZo058GN', 4, '{"title":"第1024033条・辨可下病脉证并治第二十一","description":"<p>34、伤寒七八日。身黄如橘子色。小便不利。腹微满者。属$f{茵陈蒿汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024033,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '34、伤寒七八日。身黄如橘子色。小便不利。腹微满者。属$f{茵陈蒿汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7xd6qXyy7i8', 4, '{"title":"第1024034条・辨可下病脉证并治第二十一","description":"<p>35、伤寒发热。汗出不解。心中痞鞕。呕吐而下利者。属$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024034,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '35、伤寒发热。汗出不解。心中痞鞕。呕吐而下利者。属$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uLqkel1yuDJ', 4, '{"title":"第1024035条・辨可下病脉证并治第二十一","description":"<p>36、伤寒十余日。热结在里。复往来寒热者。属$f{大柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024035,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '36、伤寒十余日。热结在里。复往来寒热者。属$f{大柴胡汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LNEtZxZKv36', 4, '{"title":"第1024036条・辨可下病脉证并治第二十一","description":"<p>37、但结胸。无大热者。以水结在胸胁也。但头微汗出者。属$f{大陷胸汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024036,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '37、但结胸。无大热者。以水结在胸胁也。但头微汗出者。属$f{大陷胸汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MU4NSPVka3C', 4, '{"title":"第1024037条・辨可下病脉证并治第二十一","description":"<p>38、伤寒六七日。结胸热实。脉沉而紧。心下痛。按之石鞕者。属$f{大陷胸汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024037,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '38、伤寒六七日。结胸热实。脉沉而紧。心下痛。按之石鞕者。属$f{大陷胸汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JjuvHDr8bZi', 4, '{"title":"第1024038条・辨可下病脉证并治第二十一","description":"<p>39、阳明病。其人多汗。以津液外出。胃中燥。大便必鞕。鞕则讝语。属$f{小承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024038,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '39、阳明病。其人多汗。以津液外出。胃中燥。大便必鞕。鞕则讝语。属$f{小承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EdKoX2dLYDO', 4, '{"title":"第1024039条・辨可下病脉证并治第二十一","description":"<p>40、阳明病。不吐。不下。心烦者。属$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024039,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '40、阳明病。不吐。不下。心烦者。属$f{调胃承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OvfE7fdyGhP', 4, '{"title":"第1024040条・辨可下病脉证并治第二十一","description":"<p>41、阳明病。脉迟。虽汗出。不恶寒者。其身必重。短气。腹满而喘。有潮热者。此外欲解。可攻里也手足濈然汗出者。此大便已鞕也。$f{大承气汤}主之。若汗出多。微发热恶寒者。外未解也。$f{桂枝汤}主之。其热不潮。未可与承气汤。若腹大满不通者。与$f{小承气汤}微和胃气。勿令至大泄下。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024040,"note":"","videoMemo":"","fangList":["大承气汤","桂枝汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '41、阳明病。脉迟。虽汗出。不恶寒者。其身必重。短气。腹满而喘。有潮热者。此外欲解。可攻里也手足濈然汗出者。此大便已鞕也。$f{大承气汤}主之。若汗出多。微发热恶寒者。外未解也。$f{桂枝汤}主之。其热不潮。未可与承气汤。若腹大满不通者。与$f{小承气汤}微和胃气。勿令至大泄下。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7zb39jpMTQ0', 4, '{"title":"第1024041条・辨可下病脉证并治第二十一","description":"<p>42、阳明病。潮热。大便微鞕者。可与$f{大承气汤}。不鞕者。不可与之。若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转失气者。此有燥屎也。乃可攻之。若不转失气者。此但初头鞕。后必溏。不可攻之。攻之必胀满。不能食也。欲饮水者。与水则哕。其后发热者。大便必复鞕而少也。宜以$f{小承气汤}和之。不转失气者。慎不可攻也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024041,"note":"","videoMemo":"","fangList":["大承气汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '42、阳明病。潮热。大便微鞕者。可与$f{大承气汤}。不鞕者。不可与之。若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转失气者。此有燥屎也。乃可攻之。若不转失气者。此但初头鞕。后必溏。不可攻之。攻之必胀满。不能食也。欲饮水者。与水则哕。其后发热者。大便必复鞕而少也。宜以$f{小承气汤}和之。不转失气者。慎不可攻也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DT64NePb8LP', 4, '{"title":"第1024042条・辨可下病脉证并治第二十一","description":"<p>43、阳明病。讝语。发潮热。脉滑而疾者。$f{小承气汤}主之。因与承气汤一升。腹中转气者。更服一升。若不转气者。勿更与之。明日又不大便。脉反微涩者。里虚也。为难治。不可更与承气汤。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024042,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '43、阳明病。讝语。发潮热。脉滑而疾者。$f{小承气汤}主之。因与承气汤一升。腹中转气者。更服一升。若不转气者。勿更与之。明日又不大便。脉反微涩者。里虚也。为难治。不可更与承气汤。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CSAe2wBsZC7', 4, '{"title":"第1024043条・辨可下病脉证并治第二十一","description":"<p>44、二阳并病。太阳证罢。但发潮热。手足漐。漐汗出。大便难而讝语者。下之。则愈。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024043,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '44、二阳并病。太阳证罢。但发潮热。手足漐。漐汗出。大便难而讝语者。下之。则愈。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dSwn7mEDMDp', 4, '{"title":"第1024044条・辨可下病脉证并治第二十一","description":"<p>45、病人小便不利。大便乍难乍易。时有微热。喘冒不能卧者。有燥屎也。属$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024044,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '45、病人小便不利。大便乍难乍易。时有微热。喘冒不能卧者。有燥屎也。属$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('64AchfykQOP', 4, '{"title":"第1024045条・辨可下病脉证并治第二十一","description":"<p>46、大下后。六七日不大便。烦不解。腹满痛者。此有燥屎也。所以然者。本有宿食故也。属$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1024045,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '46、大下后。六七日不大便。烦不解。腹满痛者。此有燥屎也。所以然者。本有宿食故也。属$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'Ynj6pSrvmOg');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Sw6BTP7Ylj', 4, '{"title":"第1025000条・辨发汗吐下后病脉证并治第二十二","description":"<p>1、师曰。病人脉微而涩者。此为医所病也。大发其汗。又数大下之。其人亡血。病当恶寒。后乃发热无休止。时夏月盛热。欲著复衣。冬月盛寒。欲裸其身。所以然者。阳微则恶寒。阴弱则发热。此医发其汗。使阳气微。又大下之。令阴气弱。五月之时。阳气在表。胃中虚冷。以阳气内微。不能胜冷。故欲著复衣。十一月之时。阳气在里。胃中烦热。以阴气内弱。不能胜热。故欲裸其身。又阴脉迟涩。故知亡血也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰。病人脉微而涩者。此为医所病也。大发其汗。又数大下之。其人亡血。病当恶寒。后乃发热无休止。时夏月盛热。欲著复衣。冬月盛寒。欲裸其身。所以然者。阳微则恶寒。阴弱则发热。此医发其汗。使阳气微。又大下之。令阴气弱。五月之时。阳气在表。胃中虚冷。以阳气内微。不能胜冷。故欲著复衣。十一月之时。阳气在里。胃中烦热。以阴气内弱。不能胜热。故欲裸其身。又阴脉迟涩。故知亡血也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0eRAAxtqDY2', 4, '{"title":"第1025001条・辨发汗吐下后病脉证并治第二十二","description":"<p>2、寸口脉浮大。而医反下之。此为大逆。浮则无血。大则为寒。寒气相搏。则为肠鸣。医乃不知而反饮冷水。令汗大出。水得寒气。冷必相搏。其人则䭇。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、寸口脉浮大。而医反下之。此为大逆。浮则无血。大则为寒。寒气相搏。则为肠鸣。医乃不知而反饮冷水。令汗大出。水得寒气。冷必相搏。其人则䭇。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H0kyBnuVic1', 4, '{"title":"第1025002条・辨发汗吐下后病脉证并治第二十二","description":"<p>3、太阳病。三日已发汗。若吐若下。若温针。仍不解者。此为坏病。桂枝不中与之也。观其脉证。知犯何逆。随证治之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、太阳病。三日已发汗。若吐若下。若温针。仍不解者。此为坏病。桂枝不中与之也。观其脉证。知犯何逆。随证治之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('taBEzhSaDEV', 4, '{"title":"第1025003条・辨发汗吐下后病脉证并治第二十二","description":"<p>4、脉浮数者。法当汗出而愈。若下之。身重心悸者。不可发汗。当自汗出乃解。所以然者。尺中脉微。此里虚。须表里实。津液和。便自汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、脉浮数者。法当汗出而愈。若下之。身重心悸者。不可发汗。当自汗出乃解。所以然者。尺中脉微。此里虚。须表里实。津液和。便自汗出愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MHxAeo3XDDd', 4, '{"title":"第1025004条・辨发汗吐下后病脉证并治第二十二","description":"<p>5、凡病若发汗。若吐若下若亡血。无津液。阴阳脉自和者。必自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '5、凡病若发汗。若吐若下若亡血。无津液。阴阳脉自和者。必自愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NsK5UdImNNx', 4, '{"title":"第1025005条・辨发汗吐下后病脉证并治第二十二","description":"<p>6、大下之后。复发汗。小便不利者。亡津液故也。勿治之。得小便利。必自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、大下之后。复发汗。小便不利者。亡津液故也。勿治之。得小便利。必自愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hJCpCxd7noj', 4, '{"title":"第1025006条・辨发汗吐下后病脉证并治第二十二","description":"<p>7、下之后。复发汗。必振寒。脉微细。所以然者。以内外俱虚故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '7、下之后。复发汗。必振寒。脉微细。所以然者。以内外俱虚故也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ezIYsen0goP', 4, '{"title":"第1025007条・辨发汗吐下后病脉证并治第二十二","description":"<p>8、本发汗而复下之。此为逆也。若先发汗。治不为逆。本先下之。而反汗之。为逆。若先下之。治不为逆。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '8、本发汗而复下之。此为逆也。若先发汗。治不为逆。本先下之。而反汗之。为逆。若先下之。治不为逆。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DxtUVMEwOeY', 4, '{"title":"第1025008条・辨发汗吐下后病脉证并治第二十二","description":"<p>9、太阳病。先下而不愈。因复发汗。以此表里俱虚。其人因致冒。冒家汗出自愈。所以然者。汗出表和故也。得表和。然后复下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '9、太阳病。先下而不愈。因复发汗。以此表里俱虚。其人因致冒。冒家汗出自愈。所以然者。汗出表和故也。得表和。然后复下之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wemxpmwndg9', 4, '{"title":"第1025009条・辨发汗吐下后病脉证并治第二十二","description":"<p>10、得病六七日。脉迟浮弱。恶风寒。手足温。医二三下之。不能食而胁下满痛。面目及身黄。颈项强。小便难者。与$f{柴胡汤}。后必下重。本渴饮水而呕者。$u{柴胡}不中与也。食谷者哕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025009,"note":"","videoMemo":"","fangList":["柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '10、得病六七日。脉迟浮弱。恶风寒。手足温。医二三下之。不能食而胁下满痛。面目及身黄。颈项强。小便难者。与$f{柴胡汤}。后必下重。本渴饮水而呕者。$u{柴胡}不中与也。食谷者哕。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xPT9uhqB2E1', 4, '{"title":"第1025010条・辨发汗吐下后病脉证并治第二十二","description":"<p>11、太阳病。二三日不能卧。但欲起。心下必结。脉微弱者。此本有寒分也。反下之。若利止。必作结胸。未止者。四日复下之。此作协热利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '11、太阳病。二三日不能卧。但欲起。心下必结。脉微弱者。此本有寒分也。反下之。若利止。必作结胸。未止者。四日复下之。此作协热利也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mYNiiGN06Vt', 4, '{"title":"第1025011条・辨发汗吐下后病脉证并治第二十二","description":"<p>12、太阳病。下之。其脉促。$a{（一作纵）}不结胸者。此为欲解也。脉浮者必结胸。脉紧者必咽痛。脉弦者必两胁拘急。脉细数者。头痛未止。脉沉紧者。必欲呕。脉沉滑者。协热利。脉浮滑者。必下血。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、太阳病。下之。其脉促。$a{（一作纵）}不结胸者。此为欲解也。脉浮者必结胸。脉紧者必咽痛。脉弦者必两胁拘急。脉细数者。头痛未止。脉沉紧者。必欲呕。脉沉滑者。协热利。脉浮滑者。必下血。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xSwn20T3H3q', 4, '{"title":"第1025012条・辨发汗吐下后病脉证并治第二十二","description":"<p>13、太阳少阳并病。而反下之。成结胸。心下鞕。下利不止。水浆不下。其人心烦。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '13、太阳少阳并病。而反下之。成结胸。心下鞕。下利不止。水浆不下。其人心烦。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ilsnYUdiN9S', 4, '{"title":"第1025013条・辨发汗吐下后病脉证并治第二十二","description":"<p>14、脉浮而紧。而复下之。紧反入里。则作痞。按之自濡。但气痞耳。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '14、脉浮而紧。而复下之。紧反入里。则作痞。按之自濡。但气痞耳。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6lJ3cve3Vp7', 4, '{"title":"第1025014条・辨发汗吐下后病脉证并治第二十二","description":"<p>15、伤寒吐下发汗后。虚烦。脉甚微。八九日心下痞鞕。胁下痛。气上冲咽喉。眩冒。经脉动愓者。久而成痿。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '15、伤寒吐下发汗后。虚烦。脉甚微。八九日心下痞鞕。胁下痛。气上冲咽喉。眩冒。经脉动愓者。久而成痿。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LxrOmJX641q', 4, '{"title":"第1025015条・辨发汗吐下后病脉证并治第二十二","description":"<p>16、阳明病。能食。下之不解者。其人不能食。若攻其热。必哕。所以然者。胃中虚冷故也。以其人本虚。攻其热。必哕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '16、阳明病。能食。下之不解者。其人不能食。若攻其热。必哕。所以然者。胃中虚冷故也。以其人本虚。攻其热。必哕。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WKBjCzK92y6', 4, '{"title":"第1025016条・辨发汗吐下后病脉证并治第二十二","description":"<p>17、阳明病。脉迟。食难用饱。饱则发烦。头眩。必小便难。此欲作谷疽。虽下之。腹满如故。所以然者。脉迟故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '17、阳明病。脉迟。食难用饱。饱则发烦。头眩。必小便难。此欲作谷疽。虽下之。腹满如故。所以然者。脉迟故也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1DV2hFmIgUF', 4, '{"title":"第1025017条・辨发汗吐下后病脉证并治第二十二","description":"<p>18、夫病。阳多者热。下之则鞕。汗多。极发其汗。亦鞕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '18、夫病。阳多者热。下之则鞕。汗多。极发其汗。亦鞕。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oQAz8uC5sba', 4, '{"title":"第1025018条・辨发汗吐下后病脉证并治第二十二","description":"<p>19、太阳病。寸缓关浮尺弱。其人发热汗出。复恶寒。不呕。但心下痞者。此以医下之也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '19、太阳病。寸缓关浮尺弱。其人发热汗出。复恶寒。不呕。但心下痞者。此以医下之也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u2xEaOAe6p6', 4, '{"title":"第1025019条・辨发汗吐下后病脉证并治第二十二","description":"<p>20、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。若下之。必胸下结鞕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '20、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。若下之。必胸下结鞕。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xfpG7mttU3A', 4, '{"title":"第1025020条・辨发汗吐下后病脉证并治第二十二","description":"<p>21、伤寒大吐大下之。极虚。复极汗者。其人外气怫郁。复与之水。以发其汗。因得哕。所以然者。胃中寒冷故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '21、伤寒大吐大下之。极虚。复极汗者。其人外气怫郁。复与之水。以发其汗。因得哕。所以然者。胃中寒冷故也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xykCUoL7dTy', 4, '{"title":"第1025021条・辨发汗吐下后病脉证并治第二十二","description":"<p>22、吐利发汗后。脉平。小烦者。以新虚。不胜谷气故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '22、吐利发汗后。脉平。小烦者。以新虚。不胜谷气故也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dH2xjpN2riS', 4, '{"title":"第1025022条・辨发汗吐下后病脉证并治第二十二","description":"<p>23、太阳病。医发汗。遂发热恶寒。因复下之。心下痞。表里俱虚。阴阳气并竭。无阳则阴独。复加烧针。因胸烦。面色青黄。肤瞤者。难治。今色微黄。手足温者。易愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '23、太阳病。医发汗。遂发热恶寒。因复下之。心下痞。表里俱虚。阴阳气并竭。无阳则阴独。复加烧针。因胸烦。面色青黄。肤瞤者。难治。今色微黄。手足温者。易愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U0ePqm7et7W', 4, '{"title":"第1025023条・辨发汗吐下后病脉证并治第二十二","description":"<p>24、太阳病。得之八九日。如疟状。发热恶寒。热多寒少。其人不呕。清便欲自可。一日二三度发。脉微缓者。为欲愈也。脉微而恶寒者。此阴阳俱虚。不可更发汗。更下更吐也。面色反有热色者。未欲解也。以其不能得小汗出。身必痒。属$f{桂枝麻黄各半汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025023,"note":"","videoMemo":"","fangList":["桂枝麻黄各半汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '24、太阳病。得之八九日。如疟状。发热恶寒。热多寒少。其人不呕。清便欲自可。一日二三度发。脉微缓者。为欲愈也。脉微而恶寒者。此阴阳俱虚。不可更发汗。更下更吐也。面色反有热色者。未欲解也。以其不能得小汗出。身必痒。属$f{桂枝麻黄各半汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bcRqdZt2qj6', 4, '{"title":"第1025024条・辨发汗吐下后病脉证并治第二十二","description":"<p>25、服$f{桂枝汤}。或下之。仍头项强痛。翕翕发热。无汗。心下满微痛。小便不利者。属$f{桂枝去桂加茯苓白术汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025024,"note":"","videoMemo":"","fangList":["桂枝汤","桂枝去桂加茯苓白术汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '25、服$f{桂枝汤}。或下之。仍头项强痛。翕翕发热。无汗。心下满微痛。小便不利者。属$f{桂枝去桂加茯苓白术汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JgglPglebW3', 4, '{"title":"第1025025条・辨发汗吐下后病脉证并治第二十二","description":"<p>26、太阳病。先发汗不解。而下之。脉浮者。不愈。浮为在外。而反下之。故令不愈。今脉浮故在外。当须解外则愈。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025025,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '26、太阳病。先发汗不解。而下之。脉浮者。不愈。浮为在外。而反下之。故令不愈。今脉浮故在外。当须解外则愈。宜$f{桂枝汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yuz3kUHBQ76', 4, '{"title":"第1025026条・辨发汗吐下后病脉证并治第二十二","description":"<p>27、下之后复发汗。昼日烦躁不得眠。夜而安静。不呕不渴。无表证。脉沉微。身无大热者。属$f{干姜附子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025026,"note":"","videoMemo":"","fangList":["干姜附子汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '27、下之后复发汗。昼日烦躁不得眠。夜而安静。不呕不渴。无表证。脉沉微。身无大热者。属$f{干姜附子汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H2YmBQ8FTWq', 4, '{"title":"第1025027条・辨发汗吐下后病脉证并治第二十二","description":"<p>28、伤寒若吐若下后。心下逆满。气上冲胸。起则头眩。脉沉紧。发汗则动经。身为振振摇者。属$f{茯苓桂枝白术甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025027,"note":"","videoMemo":"","fangList":["茯苓桂枝白术甘草汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '28、伤寒若吐若下后。心下逆满。气上冲胸。起则头眩。脉沉紧。发汗则动经。身为振振摇者。属$f{茯苓桂枝白术甘草汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KX7YItZMNUM', 4, '{"title":"第1025028条・辨发汗吐下后病脉证并治第二十二","description":"<p>29、发汗若下之后。病仍不解。烦躁者。属$f{茯苓四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025028,"note":"","videoMemo":"","fangList":["茯苓四逆汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '29、发汗若下之后。病仍不解。烦躁者。属$f{茯苓四逆汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y1DwXlDSKyT', 4, '{"title":"第1025029条・辨发汗吐下后病脉证并治第二十二","description":"<p>30、发汗吐下后。虚烦不得眠。若剧者。必反复颠倒。心中懊憹。属$f{栀子豉汤}。若少气者。$f{栀子甘草豉汤}。若呕者。$f{栀子生姜豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025029,"note":"","videoMemo":"","fangList":["栀子豉汤","栀子甘草豉汤","栀子生姜豉汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '30、发汗吐下后。虚烦不得眠。若剧者。必反复颠倒。心中懊憹。属$f{栀子豉汤}。若少气者。$f{栀子甘草豉汤}。若呕者。$f{栀子生姜豉汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a66EsRZ5W25', 4, '{"title":"第1025030条・辨发汗吐下后病脉证并治第二十二","description":"<p>31、发汗若下之而烦热。胸中窒者。属$f{栀子豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025030,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '31、发汗若下之而烦热。胸中窒者。属$f{栀子豉汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('byaL56Jhwm0', 4, '{"title":"第1025031条・辨发汗吐下后病脉证并治第二十二","description":"<p>32、太阳病。过经十余日。心下温温欲吐。而胸中痛。大便反溏。腹微满。郁郁微烦。先此时极吐下者。与$f{调胃承气汤}。若不尔者。不可与。但欲呕。胸中痛。微溏者。此非$f{柴胡汤}证。以呕故。知极吐下也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025031,"note":"","videoMemo":"","fangList":["调胃承气汤","柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '32、太阳病。过经十余日。心下温温欲吐。而胸中痛。大便反溏。腹微满。郁郁微烦。先此时极吐下者。与$f{调胃承气汤}。若不尔者。不可与。但欲呕。胸中痛。微溏者。此非$f{柴胡汤}证。以呕故。知极吐下也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dehKKMugqOF', 4, '{"title":"第1025032条・辨发汗吐下后病脉证并治第二十二","description":"<p>33、太阳病。重发汗而复下之。不大便。五六日。舌上燥而渴。日晡所。小有潮热。$a{（一云。日晡所发。心胸大烦。）}从心下至少腹。鞕满而痛。不可近者。属$f{大陷胸汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025032,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '33、太阳病。重发汗而复下之。不大便。五六日。舌上燥而渴。日晡所。小有潮热。$a{（一云。日晡所发。心胸大烦。）}从心下至少腹。鞕满而痛。不可近者。属$f{大陷胸汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uqJzWSNLC9e', 4, '{"title":"第1025033条・辨发汗吐下后病脉证并治第二十二","description":"<p>34、伤寒五六日已发汗。而复下之。胸胁满。微结。小便不利。渴而不呕。但头汗出。往来寒热心烦者。此为未解也。属$f{柴胡桂枝干姜汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025033,"note":"","videoMemo":"","fangList":["柴胡桂枝干姜汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '34、伤寒五六日已发汗。而复下之。胸胁满。微结。小便不利。渴而不呕。但头汗出。往来寒热心烦者。此为未解也。属$f{柴胡桂枝干姜汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('asOXhDbdTq7', 4, '{"title":"第1025034条・辨发汗吐下后病脉证并治第二十二","description":"<p>35、伤寒发汗。若吐若下。解后。心下痞鞕。噫气不除者。属$f{旋覆代赭汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025034,"note":"","videoMemo":"","fangList":["旋覆代赭汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '35、伤寒发汗。若吐若下。解后。心下痞鞕。噫气不除者。属$f{旋覆代赭汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('74o2laMAl5P', 4, '{"title":"第1025035条・辨发汗吐下后病脉证并治第二十二","description":"<p>36、伤寒大下之。复发汗。心下痞。恶寒者。表未解也。不可攻痞。当先解表。表解。乃攻痞。解表。宜$f{桂枝汤}。用前方。攻痞。宜$f{大黄黄连泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025035,"note":"","videoMemo":"","fangList":["桂枝汤","大黄黄连泻心汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '36、伤寒大下之。复发汗。心下痞。恶寒者。表未解也。不可攻痞。当先解表。表解。乃攻痞。解表。宜$f{桂枝汤}。用前方。攻痞。宜$f{大黄黄连泻心汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LDpl3iaL95w', 4, '{"title":"第1025036条・辨发汗吐下后病脉证并治第二十二","description":"<p>37、伤寒若吐下后。七八日不解。热结在里。表里俱热。时时恶风。大渴。舌上干燥而烦欲饮水数升者。属$f{白虎加人参汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025036,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '37、伤寒若吐下后。七八日不解。热结在里。表里俱热。时时恶风。大渴。舌上干燥而烦欲饮水数升者。属$f{白虎加人参汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YosXu06bQ7F', 4, '{"title":"第1025037条・辨发汗吐下后病脉证并治第二十二","description":"<p>38、伤寒若吐若下后。不解。不大便。五六日。上至十余日。日晡所发潮热。不恶寒。独语如见鬼状。若剧者。发则不识人。循衣摸床。惕而不安。$a{（一云。顺衣妄撮。怵惕不安。）}微喘直视。脉弦者生。涩者死。微者但发热。讝语者。属$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025037,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '38、伤寒若吐若下后。不解。不大便。五六日。上至十余日。日晡所发潮热。不恶寒。独语如见鬼状。若剧者。发则不识人。循衣摸床。惕而不安。$a{（一云。顺衣妄撮。怵惕不安。）}微喘直视。脉弦者生。涩者死。微者但发热。讝语者。属$f{大承气汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qZrpJqZYjqp', 4, '{"title":"第1025038条・辨发汗吐下后病脉证并治第二十二","description":"<p>39、三阳合病。腹满。身重。难以转侧。口不仁。面垢。$a{（又作枯。一云向经。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '39、三阳合病。腹满。身重。难以转侧。口不仁。面垢。$a{（又作枯。一云向经。）}', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('smu5j0p9xJl', 4, '{"title":"第1025039条・辨发汗吐下后病脉证并治第二十二","description":"<p>40、讝语遗尿。发汗则讝语。下之。则额上生汗。若手足逆冷自汗出者。属$f{白虎汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025039,"note":"","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '40、讝语遗尿。发汗则讝语。下之。则额上生汗。若手足逆冷自汗出者。属$f{白虎汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mSHobudELRr', 4, '{"title":"第1025040条・辨发汗吐下后病脉证并治第二十二","description":"<p>41、阳明病。脉浮而紧。咽燥。口苦。腹满而喘。发热汗出。不恶寒。反恶热。身重。若发汗则躁。心愦愦而反讝语。若加温针。必怵惕烦躁不得眠。若下之。则胃中空虚。客气动膈。心中懊憹。舌上胎者。属$f{栀子豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025040,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '41、阳明病。脉浮而紧。咽燥。口苦。腹满而喘。发热汗出。不恶寒。反恶热。身重。若发汗则躁。心愦愦而反讝语。若加温针。必怵惕烦躁不得眠。若下之。则胃中空虚。客气动膈。心中懊憹。舌上胎者。属$f{栀子豉汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KOgOFUO8i3Z', 4, '{"title":"第1025041条・辨发汗吐下后病脉证并治第二十二","description":"<p>42、阳明病。下之。心中懊憹而烦。胃中有燥屎者。可攻。腹微满。初头鞕。后必溏。不可攻之。若有燥屎者。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025041,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '42、阳明病。下之。心中懊憹而烦。胃中有燥屎者。可攻。腹微满。初头鞕。后必溏。不可攻之。若有燥屎者。宜$f{大承气汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hue9IJGruBz', 4, '{"title":"第1025042条・辨发汗吐下后病脉证并治第二十二","description":"<p>43、太阳病。若吐若下。若发汗后。微烦。小便数。大便因鞕者。与$f{小承气汤}和之。愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025042,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '43、太阳病。若吐若下。若发汗后。微烦。小便数。大便因鞕者。与$f{小承气汤}和之。愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lsTJl7emVg6', 4, '{"title":"第1025043条・辨发汗吐下后病脉证并治第二十二","description":"<p>44、大汗。若大下而厥冷者。属$f{四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025043,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '44、大汗。若大下而厥冷者。属$f{四逆汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XshR2lWPkjN', 4, '{"title":"第1025044条・辨发汗吐下后病脉证并治第二十二","description":"<p>45、太阳病。下之后。其气上冲者。可与$f{桂枝汤}。若不上冲者。不得与之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025044,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '45、太阳病。下之后。其气上冲者。可与$f{桂枝汤}。若不上冲者。不得与之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FuCXyAvJOhk', 4, '{"title":"第1025045条・辨发汗吐下后病脉证并治第二十二","description":"<p>46、太阳病。下之后。脉促。胸满者。属$f{桂枝去芍药汤}。$a{（促一作纵）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025045,"note":"","videoMemo":"","fangList":["桂枝去芍药汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '46、太阳病。下之后。脉促。胸满者。属$f{桂枝去芍药汤}。$a{（促一作纵）}', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r15vZy3fUVE', 4, '{"title":"第1025046条・辨发汗吐下后病脉证并治第二十二","description":"<p>47、若微寒者。属$f{桂枝去芍药加附子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025046,"note":"","videoMemo":"","fangList":["桂枝去芍药加附子汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '47、若微寒者。属$f{桂枝去芍药加附子汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZZZ12sDiRbM', 4, '{"title":"第1025047条・辨发汗吐下后病脉证并治第二十二","description":"<p>48、太阳病桂枝证。医反下之。利遂不止。脉促者。表未解也。喘而汗出者。属$f{葛根黄芩黄连汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025047,"note":"","videoMemo":"","fangList":["葛根黄芩黄连汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '48、太阳病桂枝证。医反下之。利遂不止。脉促者。表未解也。喘而汗出者。属$f{葛根黄芩黄连汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Iqp4aFm75oc', 4, '{"title":"第1025048条・辨发汗吐下后病脉证并治第二十二","description":"<p>49、太阳病。下之微喘者。表未解故也。属$f{桂枝加厚朴杏子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025048,"note":"","videoMemo":"","fangList":["桂枝加厚朴杏子汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '49、太阳病。下之微喘者。表未解故也。属$f{桂枝加厚朴杏子汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qRcVpqF1qZg', 4, '{"title":"第1025049条・辨发汗吐下后病脉证并治第二十二","description":"<p>50、伤寒不大便六七日。头痛有热者。与承气汤。其小便清者。$a{（一云大便青。）}知不在里。仍在表也。当须发汗。若头痛者。必衄。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025049,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '50、伤寒不大便六七日。头痛有热者。与承气汤。其小便清者。$a{（一云大便青。）}知不在里。仍在表也。当须发汗。若头痛者。必衄。宜$f{桂枝汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CqQ4NZw8oTo', 4, '{"title":"第1025050条・辨发汗吐下后病脉证并治第二十二","description":"<p>51、伤寒五六日。大下之后。身热不去。心中结痛者。未欲解也。属$f{栀子豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025050,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '51、伤寒五六日。大下之后。身热不去。心中结痛者。未欲解也。属$f{栀子豉汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8HFpb3NQxfj', 4, '{"title":"第1025051条・辨发汗吐下后病脉证并治第二十二","description":"<p>52、伤寒下后。心烦腹满。卧起不安者。属$f{栀子厚朴汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025051,"note":"","videoMemo":"","fangList":["栀子厚朴汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '52、伤寒下后。心烦腹满。卧起不安者。属$f{栀子厚朴汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0od2nFGyXxU', 4, '{"title":"第1025052条・辨发汗吐下后病脉证并治第二十二","description":"<p>53、伤寒医以丸药大下之。身热不去。微烦者。属$f{栀子干姜汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025052,"note":"","videoMemo":"","fangList":["栀子干姜汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '53、伤寒医以丸药大下之。身热不去。微烦者。属$f{栀子干姜汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zf5hIObYc0I', 4, '{"title":"第1025053条・辨发汗吐下后病脉证并治第二十二","description":"<p>54、凡用栀子汤。病人旧微溏者。不可与服之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025053,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '54、凡用栀子汤。病人旧微溏者。不可与服之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1cCh72LQ2ZL', 4, '{"title":"第1025054条・辨发汗吐下后病脉证并治第二十二","description":"<p>55、伤寒医下之。续得下利。清谷不止。身疼痛者。急当救里。后身疼痛。清便自调者。急当救表。救里。宜$f{四逆汤}。救表。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025054,"note":"","videoMemo":"","fangList":["四逆汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '55、伤寒医下之。续得下利。清谷不止。身疼痛者。急当救里。后身疼痛。清便自调者。急当救表。救里。宜$f{四逆汤}。救表。宜$f{桂枝汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BEsXsMfHrr6', 4, '{"title":"第1025055条・辨发汗吐下后病脉证并治第二十二","description":"<p>56、太阳病。过经十余日。反二三下之。后四五日。柴胡证仍在者。先与小柴胡。呕不止。心下急。$a{（一云。呕止小安。）}郁郁微烦者。为未解也。可与$f{大柴胡汤}。下之则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025055,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '56、太阳病。过经十余日。反二三下之。后四五日。柴胡证仍在者。先与小柴胡。呕不止。心下急。$a{（一云。呕止小安。）}郁郁微烦者。为未解也。可与$f{大柴胡汤}。下之则愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HHXJA9XyCOl', 4, '{"title":"第1025056条・辨发汗吐下后病脉证并治第二十二","description":"<p>57、伤寒十三日不解。胸胁满而呕。日晡所发潮热。已而微利。此本柴胡。下之不得利。今反利者。知医以丸药下之。此非其治也。潮热者。实也。先服$f{小柴胡汤}以解外。后以$f{柴胡加芒硝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025056,"note":"","videoMemo":"","fangList":["小柴胡汤","柴胡加芒硝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '57、伤寒十三日不解。胸胁满而呕。日晡所发潮热。已而微利。此本柴胡。下之不得利。今反利者。知医以丸药下之。此非其治也。潮热者。实也。先服$f{小柴胡汤}以解外。后以$f{柴胡加芒硝汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('02WNxuNgoHR', 4, '{"title":"第1025057条・辨发汗吐下后病脉证并治第二十二","description":"<p>58、伤寒十三日。过经讝语者。以有热也。当以汤下之。若小便利者。大便当鞕。而反下利。脉调和者。知医以丸药下之。非其治也。若自下利者。脉当微厥。今反和者。此为内实也。属$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025057,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '58、伤寒十三日。过经讝语者。以有热也。当以汤下之。若小便利者。大便当鞕。而反下利。脉调和者。知医以丸药下之。非其治也。若自下利者。脉当微厥。今反和者。此为内实也。属$f{调胃承气汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('syG8s2g5sMo', 4, '{"title":"第1025058条・辨发汗吐下后病脉证并治第二十二","description":"<p>59、伤寒八九日。下之胸满烦惊。小便不利。讝语。一身尽重。不可转侧者。属$f{柴胡加龙骨牡蛎汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025058,"note":"","videoMemo":"","fangList":["柴胡加龙骨牡蛎汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '59、伤寒八九日。下之胸满烦惊。小便不利。讝语。一身尽重。不可转侧者。属$f{柴胡加龙骨牡蛎汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vXko1RHUl2', 4, '{"title":"第1025059条・辨发汗吐下后病脉证并治第二十二","description":"<p>60、火逆下之。因烧针烦躁者。属$f{桂枝甘草龙骨牡蛎汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025059,"note":"","videoMemo":"","fangList":["桂枝甘草龙骨牡蛎汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '60、火逆下之。因烧针烦躁者。属$f{桂枝甘草龙骨牡蛎汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KmzJeX4yzRQ', 4, '{"title":"第1025060条・辨发汗吐下后病脉证并治第二十二","description":"<p>61、太阳病。脉浮而动数。浮则为风。数则为热。动则为痛。数则为虚。头痛发热。微盗汗出而反恶寒者。表未解也。医反下之。动数变迟。膈内拒痛。$a{（一云头痛即眩。）}胃中空虚。客气动膈。短气躁烦。心中懊憹。阳气内陷。心下因鞕。则为结胸。属$f{大陷胸汤}证。若不结胸。但头汗出。余处无汗。剂颈而还。小便不利。身必发黄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025060,"note":"","videoMemo":"","fangList":["大陷胸汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '61、太阳病。脉浮而动数。浮则为风。数则为热。动则为痛。数则为虚。头痛发热。微盗汗出而反恶寒者。表未解也。医反下之。动数变迟。膈内拒痛。$a{（一云头痛即眩。）}胃中空虚。客气动膈。短气躁烦。心中懊憹。阳气内陷。心下因鞕。则为结胸。属$f{大陷胸汤}证。若不结胸。但头汗出。余处无汗。剂颈而还。小便不利。身必发黄。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oGLd6NFpFpx', 4, '{"title":"第1025061条・辨发汗吐下后病脉证并治第二十二","description":"<p>62、伤寒五六日。呕而发热者。$f{柴胡汤}证具。而以他药下之。$u{柴胡}证仍在者。复与$f{柴胡汤}。此虽已下之不为逆。必蒸蒸而振。却发热汗出而解。若心下满而鞕痛者。此为结胸也。$f{大陷胸汤}主之。用前方。但满而不痛者。此为痞。$u{柴胡}不中与之。属$f{半夏泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025061,"note":"","videoMemo":"","fangList":["柴胡汤","大陷胸汤","半夏泻心汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '62、伤寒五六日。呕而发热者。$f{柴胡汤}证具。而以他药下之。$u{柴胡}证仍在者。复与$f{柴胡汤}。此虽已下之不为逆。必蒸蒸而振。却发热汗出而解。若心下满而鞕痛者。此为结胸也。$f{大陷胸汤}主之。用前方。但满而不痛者。此为痞。$u{柴胡}不中与之。属$f{半夏泻心汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UznWQ2wKFHC', 4, '{"title":"第1025062条・辨发汗吐下后病脉证并治第二十二","description":"<p>63、本以下之。故心下痞。与$f{泻心汤}。痞不解。其人渴而口燥烦。小便不利者。属$f{五苓散}。$a{（一方云。忍之一日乃愈。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025062,"note":"","videoMemo":"","fangList":["泻心汤","五苓散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '63、本以下之。故心下痞。与$f{泻心汤}。痞不解。其人渴而口燥烦。小便不利者。属$f{五苓散}。$a{（一方云。忍之一日乃愈。）}', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B0XCzwdIc13', 4, '{"title":"第1025063条・辨发汗吐下后病脉证并治第二十二","description":"<p>64、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞鞕而满。干呕心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。此非结热。但以胃中虚。客气上逆。故使鞕也。属$f{甘草泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025063,"note":"","videoMemo":"","fangList":["甘草泻心汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '64、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞鞕而满。干呕心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。此非结热。但以胃中虚。客气上逆。故使鞕也。属$f{甘草泻心汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IwuU5IiDv40', 4, '{"title":"第1025064条・辨发汗吐下后病脉证并治第二十二","description":"<p>65、伤寒服汤药。下利不止。心下痞鞕。服泻心汤已。复以他药下之。利不止。医以理中与之。利益甚。理中。理中焦。此利在下焦。属$f{赤石脂禹余粮汤}。复不止者。当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025064,"note":"","videoMemo":"","fangList":["赤石脂禹余粮汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '65、伤寒服汤药。下利不止。心下痞鞕。服泻心汤已。复以他药下之。利不止。医以理中与之。利益甚。理中。理中焦。此利在下焦。属$f{赤石脂禹余粮汤}。复不止者。当利其小便。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0dJ5FEPr4X', 4, '{"title":"第1025065条・辨发汗吐下后病脉证并治第二十二","description":"<p>66、太阳病。外证未除。而数下之。遂协热而利。利下不止。心下痞鞕。表里不解者。属$f{桂枝人参汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025065,"note":"","videoMemo":"","fangList":["桂枝人参汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '66、太阳病。外证未除。而数下之。遂协热而利。利下不止。心下痞鞕。表里不解者。属$f{桂枝人参汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GJtKAHojL69', 4, '{"title":"第1025066条・辨发汗吐下后病脉证并治第二十二","description":"<p>67、下后不可更行$f{桂枝汤}。汗出而喘。无大热者。属$f{麻黄杏仁甘草石膏汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025066,"note":"","videoMemo":"","fangList":["桂枝汤","麻黄杏仁甘草石膏汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '67、下后不可更行$f{桂枝汤}。汗出而喘。无大热者。属$f{麻黄杏仁甘草石膏汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WqYjcA5m0jP', 4, '{"title":"第1025067条・辨发汗吐下后病脉证并治第二十二","description":"<p>68、阳明病。下之。其外有热。手足温。不结胸。心中懊憹。饥不能食。但头汗出者。属$f{栀子豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025067,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '68、阳明病。下之。其外有热。手足温。不结胸。心中懊憹。饥不能食。但头汗出者。属$f{栀子豉汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JXVSNjnW2Q9', 4, '{"title":"第1025068条・辨发汗吐下后病脉证并治第二十二","description":"<p>69、伤寒吐后。腹胀满者。属$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025068,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '69、伤寒吐后。腹胀满者。属$f{调胃承气汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h5nATJzTvdg', 4, '{"title":"第1025069条・辨发汗吐下后病脉证并治第二十二","description":"<p>70、病人无表里证。发热七八日。脉虽浮数者。可下之。假令已下。脉数不解。今热则消谷。喜饥。至六七日。不大便者。有瘀血。属$f{抵当汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025069,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '70、病人无表里证。发热七八日。脉虽浮数者。可下之。假令已下。脉数不解。今热则消谷。喜饥。至六七日。不大便者。有瘀血。属$f{抵当汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y3rudOAXCoD', 4, '{"title":"第1025070条・辨发汗吐下后病脉证并治第二十二","description":"<p>71、本太阳病。医反下之。因尔腹满。时痛者。属太阴也。属$f{桂枝加芍药汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025070,"note":"","videoMemo":"","fangList":["桂枝加芍药汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '71、本太阳病。医反下之。因尔腹满。时痛者。属太阴也。属$f{桂枝加芍药汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bvw1LKpLSc9', 4, '{"title":"第1025071条・辨发汗吐下后病脉证并治第二十二","description":"<p>72、伤寒六七日。大下。寸脉沉而迟。手足厥逆。下部脉不至。喉咽不利。唾脓血。泄利不止者。为难治。属$f{麻黄升麻汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025071,"note":"","videoMemo":"","fangList":["麻黄升麻汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '72、伤寒六七日。大下。寸脉沉而迟。手足厥逆。下部脉不至。喉咽不利。唾脓血。泄利不止者。为难治。属$f{麻黄升麻汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('67WdJ7LGiYG', 4, '{"title":"第1025072条・辨发汗吐下后病脉证并治第二十二","description":"<p>73、伤寒本自寒。下医复吐下之。寒格更逆吐下。若食入口。即吐。属$f{干姜黄芩黄连人参汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1025072,"note":"","videoMemo":"","fangList":["干姜黄芩黄连人参汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '73、伤寒本自寒。下医复吐下之。寒格更逆吐下。若食入口。即吐。属$f{干姜黄芩黄连人参汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'iGATh38eD0j');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EuApOVohTIN', 4, '{"title":"第1026000条・伤寒论后序","description":"<p>        夫治伤寒之法。历观诸家方书。得仲景之多者。惟孙思邈。犹曰见太医疗伤寒。惟大青知母等诸冷物投之。极与仲景本意相反。又曰。寻方之大意。不过三种。一则桂枝。二则麻黄。三则青龙。凡疗伤寒不出之也。呜呼。是未知法之深者也。奈何仲景之意。治病发于阳者。以桂枝生姜大枣之类。发于阴者。以干姜甘草附子之类。非谓全用温热药。盖取素问辛甘发散之说。且风与寒。非辛甘不能发散之也。而又中风自汗。用桂枝。伤寒无汗。用麻黄。中风见寒脉。伤寒见风脉。用青龙。若不知此。欲治伤寒者。是未得其门矣。然则此之三方。春冬所宜用之。若夏秋之时。病多中暍。当行白虎也。故阴阳大论云。脉盛身寒。得之伤寒。脉虚身热。得之伤暑。又云。五月六月。阳气已盛。为寒所折。病热则重。别论云。太阳中热暍是也。其人汗出恶寒。身热而渴。白虎主之。若误服桂枝麻黄辈。未有不黄发斑出。脱血而得生者。此古人所未至。故附于卷之末云。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1026000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '夫治伤寒之法。历观诸家方书。得仲景之多者。惟孙思邈。犹曰见太医疗伤寒。惟大青知母等诸冷物投之。极与仲景本意相反。又曰。寻方之大意。不过三种。一则桂枝。二则麻黄。三则青龙。凡疗伤寒不出之也。呜呼。是未知法之深者也。奈何仲景之意。治病发于阳者。以桂枝生姜大枣之类。发于阴者。以干姜甘草附子之类。非谓全用温热药。盖取素问辛甘发散之说。且风与寒。非辛甘不能发散之也。而又中风自汗。用桂枝。伤寒无汗。用麻黄。中风见寒脉。伤寒见风脉。用青龙。若不知此。欲治伤寒者。是未得其门矣。然则此之三方。春冬所宜用之。若夏秋之时。病多中暍。当行白虎也。故阴阳大论云。脉盛身寒。得之伤寒。脉虚身热。得之伤暑。又云。五月六月。阳气已盛。为寒所折。病热则重。别论云。太阳中热暍是也。其人汗出恶寒。身热而渴。白虎主之。若误服桂枝麻黄辈。未有不黄发斑出。脱血而得生者。此古人所未至。故附于卷之末云。', '2024-09-17T00:57:28.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'ULS9sV9szS1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UN8KV9xhXQH', 1, '{"title":"桂枝汤","description":"<p>1、$f{桂枝汤} 5味</p>\n<p>$u{桂枝}$w{三两。去皮}    $u{芍药}$w{三两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上五味。㕮咀三味。以水七升。微火煮取三升。去滓。适寒温。服一升。服已。须臾啜热稀粥一升余。以助药力。温覆令一时许。遍身漐漐。微似有汗者益佳。不可令如水流漓。病必不除。若一服汗出病差。停后服。不必尽剂。若不汗。更服依前法。又不汗。后服小促其间。半日许。令三服尽。若病重者。一日一夜服。周时观之。服一剂尽。病证犹在者。更作服。若汗不出。乃服至二三剂。禁生冷粘滑肉面五辛酒酪臭恶等物。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":1,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"去皮"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":""},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"擘"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '1、$f{桂枝汤} 5味 $u{桂枝}$w{三两。去皮} $u{芍药}$w{三两} $u{甘草}$w{二两。炙} $u{生姜}$w{三两。切} $u{大枣}$w{十二枚。擘} 上五味。㕮咀三味。以水七升。微火煮取三升。去滓。适寒温。服一升。服已。须臾啜热稀粥一升余。以助药力。温覆令一时许。遍身漐漐。微似有汗者益佳。不可令如水流漓。病必不除。若一服汗出病差。停后服。不必尽剂。若不汗。更服依前法。又不汗。后服小促其间。半日许。令三服尽。若病重者。一日一夜服。周时观之。服一剂尽。病证犹在者。更作服。若汗不出。乃服至二三剂。禁生冷粘滑肉面五辛酒酪臭恶等物。', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wtdxbcD2F2X', 1, '{"title":"桂枝加葛根汤","description":"<p>2、$f{桂枝加葛根汤} 7味 </p>\n<p>$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{芍药}$w{二两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{桂枝}$w{二两。去皮}</p>\n<p>\t上七味。以水一斗。先煮麻黄葛根。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。不须啜粥。余如桂枝法。将息及禁忌。$a{臣亿等谨按仲景本论。太阳中风自汗用桂枝。伤寒无汗用麻黄。今证云汗出恶风而方中有麻黄。恐非本意也。第三卷有葛根汤证云。无汗恶风。正与此方同。是合用麻黄也。此云桂枝加葛根汤。恐是桂枝中但加葛根耳。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":2,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","大枣","甘草","生姜","芍药","麻黄","葛根"],"fangList":["123"],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":400,"suffix":"","showName":"葛根","extraProcess":""},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"去节"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":""},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"去皮"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2、$f{桂枝加葛根汤} 7味 $u{葛根}$w{四两} $u{麻黄}$w{三两。去节} $u{芍药}$w{二两} $u{生姜}$w{三两。切} $u{甘草}$w{二两。炙} $u{大枣}$w{十二枚。擘} $u{桂枝}$w{二两。去皮} 上七味。以水一斗。先煮麻黄葛根。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。不须啜粥。余如桂枝法。将息及禁忌。$a{臣亿等谨按仲景本论。太阳中风自汗用桂枝。伤寒无汗用麻黄。今证云汗出恶风而方中有麻黄。恐非本意也。第三卷有葛根汤证云。无汗恶风。正与此方同。是合用麻黄也。此云桂枝加葛根汤。恐是桂枝中但加葛根耳。}', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
