INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mGRS0zElVfe', 1, '{"title":"桂枝去芍药加附子汤","description":"<p>6、$f{桂枝去芍药加附子汤} 5味 </p>\n<p>$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{附子}$w{一枚。炮去皮破八片}</p>\n<p>\t上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加附子。将息如前法。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":6,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","甘草","生姜","大枣","附子"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '6、$f{桂枝去芍药加附子汤} 5味 $u{桂枝}$w{三两。去皮} $u{甘草}$w{二两。炙} $u{生姜}$w{三两。切} $u{大枣}$w{十二枚。擘} $u{附子}$w{一枚。炮去皮破八片} 上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加附子。将息如前法。】', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AcxIXjg2Rt5', 1, '{"title":"桂枝麻黄各半汤","description":"<p>7、$f{桂枝麻黄各半汤} 7味 </p>\n<p>$u{桂枝}$w{一两十六铢。去皮}    $u{芍药}    $u{生姜}$w{切}    $u{甘草}$w{炙}    $u{麻黄}$w{各一两。去节}    $u{大枣}$w{四枚。擘}    $u{杏仁}$w{二十四枚。汤浸去皮尖及两仁者}</p>\n<p>\t上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取一升八合。去滓。温服六合。【本云桂枝汤三合。麻黄汤三合。并为六合。顿服。将息如上法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。麻黄汤方麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。二汤各取三分之一。即得桂枝一两十六铢。芍药生姜甘草各一两。大枣四枚。杏仁二十三个。零三分枚之一。收之得二十四个。合方。详此方乃三分之一。非各半也。宜云合半汤。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":7,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","芍药","生姜","甘草","麻黄","大枣","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"一两十六铢","weight":166,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"一两","weight":100,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两","weight":100,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"一两","weight":100,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"4枚","weight":40,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"24枚","weight":240,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '7、$f{桂枝麻黄各半汤} 7味 $u{桂枝}$w{一两十六铢。去皮} $u{芍药} $u{生姜}$w{切} $u{甘草}$w{炙} $u{麻黄}$w{各一两。去节} $u{大枣}$w{四枚。擘} $u{杏仁}$w{二十四枚。汤浸去皮尖及两仁者} 上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取一升八合。去滓。温服六合。【本云桂枝汤三合。麻黄汤三合。并为六合。顿服。将息如上法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。麻黄汤方麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。二汤各取三分之一。即得桂枝一两十六铢。芍药生姜甘草各一两。大枣四枚。杏仁二十三个。零三分枚之一。收之得二十四个。合方。详此方乃三分之一。非各半也。宜云合半汤。}', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ogEAiOUPeGl', 1, '{"title":"桂枝二麻黄一汤","description":"<p>8、$f{桂枝二麻黄一汤} 7味 </p>\n<p>$u{桂枝}$w{一两十七铢。去皮}    $u{芍药}$w{一两六铢}    $u{麻黄}$w{十六铢。去节}    $u{生姜}$w{一两六铢。切}    $u{杏仁}$w{十六个。去皮尖}    $u{甘草}$w{一两二铢。炙}    $u{大枣}$w{五枚。擘}</p>\n<p>\t上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。日再服。【本云桂枝汤二分。麻黄汤一分。合为二升。分再服。今合为一方。将息如前法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两大枣十二枚。麻黄汤方。麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。桂枝汤取十二分之五。即得桂枝芍药生姜各一两六铢。甘草二十铢。大枣五枚。麻黄汤取九分之二。即得麻黄十六铢。桂枝十铢三分铢之二。收之得十一铢。甘草五铢三分铢之一。收之得六铢。杏仁十五个九分枚之四。收之得十六个。二汤所取相合。即共得桂枝一两十七铢。麻黄十六铢。生姜芍药各一两六铢。甘草一两二铢。大枣五枚。杏仁十六个。合方。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":8,"yaoCount":7,"drinkNum":2,"yaoList":["桂枝","芍药","麻黄","生姜","杏仁","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"一两十七铢","weight":171,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"一两六铢","weight":125,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"十六铢","weight":66,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两六铢","weight":125,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"16个","weight":160,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":null,"amount":"一两二铢","weight":108,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"5枚","weight":50,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '8、$f{桂枝二麻黄一汤} 7味 $u{桂枝}$w{一两十七铢。去皮} $u{芍药}$w{一两六铢} $u{麻黄}$w{十六铢。去节} $u{生姜}$w{一两六铢。切} $u{杏仁}$w{十六个。去皮尖} $u{甘草}$w{一两二铢。炙} $u{大枣}$w{五枚。擘} 上七味。以水五升。先煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。日再服。【本云桂枝汤二分。麻黄汤一分。合为二升。分再服。今合为一方。将息如前法。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两大枣十二枚。麻黄汤方。麻黄三两。桂枝二两。甘草一两。杏仁七十个。今以算法约之。桂枝汤取十二分之五。即得桂枝芍药生姜各一两六铢。甘草二十铢。大枣五枚。麻黄汤取九分之二。即得麻黄十六铢。桂枝十铢三分铢之二。收之得十一铢。甘草五铢三分铢之一。收之得六铢。杏仁十五个九分枚之四。收之得十六个。二汤所取相合。即共得桂枝一两十七铢。麻黄十六铢。生姜芍药各一两六铢。甘草一两二铢。大枣五枚。杏仁十六个。合方。}', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wo87v4nXfy6', 1, '{"title":"白虎加人参汤","description":"<p>9、$f{白虎加人参汤} 5味 </p>\n<p>$u{知母}$w{六两}    $u{石膏}$w{一斤。碎绵裹}    $u{甘草}$w{炙。二两}    $u{粳米}$w{六合}    $u{人参}$w{三两}</p>\n<p>\t上五味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":9,"yaoCount":5,"drinkNum":3,"yaoList":["知母","石膏","甘草","粳米","人参"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"六两","weight":600,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":1600,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"六合","weight":600,"suffix":"","showName":"粳米","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '9、$f{白虎加人参汤} 5味 $u{知母}$w{六两} $u{石膏}$w{一斤。碎绵裹} $u{甘草}$w{炙。二两} $u{粳米}$w{六合} $u{人参}$w{三两} 上五味。以水一斗。煮米熟汤成。去滓。温服一升。日三服。', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FPgerRj9yzh', 1, '{"title":"桂枝二越婢一汤","description":"<p>10、$f{桂枝二越婢一汤} 7味 </p>\n<p>$u{桂枝}$w{去皮}    $u{芍药}    $u{麻黄}    $u{甘草}$w{各十八铢。炙}    $u{大枣}$w{四枚。擘}    $u{生姜}$w{一两二铢。切}    $u{石膏}$w{二十四铢。碎绵裹}</p>\n<p>\t上七味。以水五升。煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。【本云当裁为越婢汤桂枝汤。合之饮一升。今合为一方。桂枝汤二分。越婢汤一分。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。越婢汤方麻黄二两。生姜三两。甘草二两。石膏半斤。大枣十五枚。今以算法约之。桂枝汤取四分之一。即得桂枝芍药生姜各十八铢。甘草十二铢。大枣三枚。越婢汤取八分之一。即得麻黄十八铢。生姜九铢。甘草六铢。石膏二十四铢。大枣一枚八分之七。弃之。二汤所取相合。即共得桂枝芍药甘草麻黄各十八铢。生姜一两三铢。石膏二十四铢。大枣四枚。合方。旧云。桂枝三。今取四分之一。即当云桂枝二也。越婢汤方。见仲景杂方中。外台秘要。一云起脾汤。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":10,"yaoCount":7,"drinkNum":2,"yaoList":["桂枝","芍药","麻黄","甘草","大枣","生姜","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"十八铢","weight":75,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"十八铢","weight":75,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"十八铢","weight":75,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":null,"amount":"十八铢","weight":75,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"4枚","weight":40,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两二铢","weight":108,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"二十四铢","weight":100,"suffix":"","showName":"石膏","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '10、$f{桂枝二越婢一汤} 7味 $u{桂枝}$w{去皮} $u{芍药} $u{麻黄} $u{甘草}$w{各十八铢。炙} $u{大枣}$w{四枚。擘} $u{生姜}$w{一两二铢。切} $u{石膏}$w{二十四铢。碎绵裹} 上七味。以水五升。煮麻黄一二沸。去上沫。内诸药。煮取二升。去滓。温服一升。【本云当裁为越婢汤桂枝汤。合之饮一升。今合为一方。桂枝汤二分。越婢汤一分。】$a{臣亿等谨按桂枝汤方。桂枝芍药生姜各三两。甘草二两。大枣十二枚。越婢汤方麻黄二两。生姜三两。甘草二两。石膏半斤。大枣十五枚。今以算法约之。桂枝汤取四分之一。即得桂枝芍药生姜各十八铢。甘草十二铢。大枣三枚。越婢汤取八分之一。即得麻黄十八铢。生姜九铢。甘草六铢。石膏二十四铢。大枣一枚八分之七。弃之。二汤所取相合。即共得桂枝芍药甘草麻黄各十八铢。生姜一两三铢。石膏二十四铢。大枣四枚。合方。旧云。桂枝三。今取四分之一。即当云桂枝二也。越婢汤方。见仲景杂方中。外台秘要。一云起脾汤。}', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h4TKm3M1atm', 1, '{"title":"桂枝去桂加茯苓白术汤","description":"<p>11、$f{桂枝去桂加茯苓白术汤} 6味 </p>\n<p>$u{芍药}$w{三两}    $u{甘草}$w{二两。炙}    $u{生姜}$w{切}    $u{白术}    $u{茯苓}$w{各三两}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上六味。以水八升。煮取三升。去滓。温服一升。小便利则愈。【本云桂枝汤。今去桂枝加茯苓白术。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":11,"yaoCount":6,"drinkNum":3,"yaoList":["芍药","甘草","生姜","白术","茯苓","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":300,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '11、$f{桂枝去桂加茯苓白术汤} 6味 $u{芍药}$w{三两} $u{甘草}$w{二两。炙} $u{生姜}$w{切} $u{白术} $u{茯苓}$w{各三两} $u{大枣}$w{十二枚。擘} 上六味。以水八升。煮取三升。去滓。温服一升。小便利则愈。【本云桂枝汤。今去桂枝加茯苓白术。】', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
