INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aSh1uxdlhZO', 1, '{"title":"调胃承气汤","description":"<p>14、$f{调胃承气汤} 3味 </p>\n<p>$u{大黄}$w{四两。去皮$u{清酒}洗}    $u{甘草}$w{二两。炙}    $u{芒硝}$w{半升}</p>\n<p>\t上三味。以水三升。煮取一升。去滓。内芒硝。更上火微煮令沸。少少温服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":14,"yaoCount":4,"drinkNum":1,"yaoList":["大黄","清酒","甘草","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"半升","weight":500,"suffix":"","showName":"芒硝","extraProcess":""}]}}', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '2024-09-17T00:59:43.000Z', '14、$f{调胃承气汤} 3味 $u{大黄}$w{四两。去皮$u{清酒}洗} $u{甘草}$w{二两。炙} $u{芒硝}$w{半升} 上三味。以水三升。煮取一升。去滓。内芒硝。更上火微煮令沸。少少温服之。', '2024-09-17T00:59:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mMrF94i5ZyT', 1, '{"title":"葛根汤","description":"<p>15、$f{葛根汤} 7味 </p>\n<p>$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{桂枝}$w{二两。去皮}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{芍药}$w{二两}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上七味。以水一斗。先煮麻黄葛根。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。余如桂枝法。将息及禁忌。诸汤皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":15,"yaoCount":7,"drinkNum":3,"yaoList":["葛根","麻黄","桂枝","生姜","甘草","芍药","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":400,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '15、$f{葛根汤} 7味 $u{葛根}$w{四两} $u{麻黄}$w{三两。去节} $u{桂枝}$w{二两。去皮} $u{生姜}$w{三两。切} $u{甘草}$w{二两。炙} $u{芍药}$w{二两} $u{大枣}$w{十二枚。擘} 上七味。以水一斗。先煮麻黄葛根。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。余如桂枝法。将息及禁忌。诸汤皆仿此。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('khms8WvgvVP', 1, '{"title":"葛根加半夏汤","description":"<p>16、$f{葛根加半夏汤} 8味 </p>\n<p>$u{葛根}$w{四两}    $u{麻黄}$w{三两。去节}    $u{甘草}$w{二两。炙}    $u{芍药}$w{二两}    $u{桂枝}$w{二两。去皮}    $u{生姜}$w{二两。切}    $u{半夏}$w{半升(洗)}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上八味。以水一斗。先煮葛根麻黄。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":16,"yaoCount":8,"drinkNum":3,"yaoList":["葛根","麻黄","甘草","芍药","桂枝","生姜","半夏","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":400,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"二两","weight":200,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '16、$f{葛根加半夏汤} 8味 $u{葛根}$w{四两} $u{麻黄}$w{三两。去节} $u{甘草}$w{二两。炙} $u{芍药}$w{二两} $u{桂枝}$w{二两。去皮} $u{生姜}$w{二两。切} $u{半夏}$w{半升(洗)} $u{大枣}$w{十二枚。擘} 上八味。以水一斗。先煮葛根麻黄。减二升。去白沫。内诸药。煮取三升。去滓。温服一升。覆取微似汗。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E9mGWasMkv6', 1, '{"title":"葛根黄芩黄连汤","description":"<p>17、$f{葛根黄芩黄连汤} 4味 </p>\n<p>$u{葛根}$w{半斤}    $u{甘草}$w{二两。炙}    $u{黄芩}$w{三两}    $u{黄连}$w{三两}</p>\n<p>\t上四味。以水八升。先煮葛根。减二升。内诸药。煮取二升。去滓。分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":17,"yaoCount":4,"drinkNum":2,"yaoList":["葛根","甘草","黄芩","黄连"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"半斤","weight":800,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"三两","weight":300,"suffix":"","showName":"黄连","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '17、$f{葛根黄芩黄连汤} 4味 $u{葛根}$w{半斤} $u{甘草}$w{二两。炙} $u{黄芩}$w{三两} $u{黄连}$w{三两} 上四味。以水八升。先煮葛根。减二升。内诸药。煮取二升。去滓。分温再服。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pN4LfbmoyFv', 1, '{"title":"麻黄汤","description":"<p>18、$f{麻黄汤} 4味 </p>\n<p>$u{麻黄}$w{三两。去节}    $u{桂枝}$w{二两。去皮}    $u{甘草}$w{一两。炙}    $u{杏仁}$w{七十个。去皮尖}</p>\n<p>\t上四味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取二升半。去滓。温服八合。覆取微似汗。不须啜粥。余如桂枝法将息。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":18,"yaoCount":4,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"70个","weight":700,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '18、$f{麻黄汤} 4味 $u{麻黄}$w{三两。去节} $u{桂枝}$w{二两。去皮} $u{甘草}$w{一两。炙} $u{杏仁}$w{七十个。去皮尖} 上四味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取二升半。去滓。温服八合。覆取微似汗。不须啜粥。余如桂枝法将息。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMhxByU3N12', 1, '{"title":"小柴胡汤","description":"<p>19、$f{小柴胡汤} 7味 </p>\n<p>$u{柴胡}$w{半斤}    $u{黄芩}    $u{人参}    $u{甘草}$w{炙}    $u{生姜}$w{各三两（切）}    $u{大枣}$w{十二枚。擘}    $u{半夏}$w{半升(洗)}</p>\n<p>\t上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。若胸中烦而不呕者。去$u{半夏}、$u{人参}。加$u{栝楼实}$w{一枚}。若渴。去$u{半夏}。加$u{人参}。$w{合前成四两半}    $u{栝楼根}$w{四两}。若腹中痛者。去$u{黄芩}。加$u{芍药}$w{三两}。若胁下痞硬。去$u{大枣}。加$u{牡蛎}$w{四两}。若心下悸、小便不利者。去$u{黄芩}。加$u{茯苓}$w{四两}。若不渴。外有微热者。去$u{人参}。加$u{桂枝}$w{三两}。温覆微汗愈。若咳者。去$u{人参}、$u{大枣}、$u{生姜}。加$u{五味子}$w{半升}    $u{干姜}$w{二两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":19,"yaoCount":15,"drinkNum":3,"yaoList":["柴胡","黄芩","人参","甘草","生姜","大枣","半夏","栝楼实","栝楼根","芍药","牡蛎","茯苓","桂枝","五味子","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"$x{腹中痛者/心下悸小便不利者去黄芩)}三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"$x{若胸中烦而不呕者/不渴外有微热者/咳者去人参)}三两$x{(若渴去半夏加人参至}四两半$x{(并栝楼根四两)}","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"$x{咳者去生姜)}三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"$x{胁下痞硬/咳者去大枣)}12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"$x{胸中烦而不呕者/渴者去半夏)}半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '19、$f{小柴胡汤} 7味 $u{柴胡}$w{半斤} $u{黄芩} $u{人参} $u{甘草}$w{炙} $u{生姜}$w{各三两（切）} $u{大枣}$w{十二枚。擘} $u{半夏}$w{半升(洗)} 上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。若胸中烦而不呕者。去$u{半夏}、$u{人参}。加$u{栝楼实}$w{一枚}。若渴。去$u{半夏}。加$u{人参}。$w{合前成四两半} $u{栝楼根}$w{四两}。若腹中痛者。去$u{黄芩}。加$u{芍药}$w{三两}。若胁下痞硬。去$u{大枣}。加$u{牡蛎}$w{四两}。若心下悸、小便不利者。去$u{黄芩}。加$u{茯苓}$w{四两}。若不渴。外有微热者。去$u{人参}。加$u{桂枝}$w{三两}。温覆微汗愈。若咳者。去$u{人参}、$u{大枣}、$u{生姜}。加$u{五味子}$w{半升} $u{干姜}$w{二两}。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dRhtzNmbPe7', 1, '{"title":"大青龙汤","description":"<p>20、$f{大青龙汤} 7味 </p>\n<p>$u{麻黄}$w{六两。去节}    $u{桂枝}$w{二两。去皮}    $u{甘草}$w{二两。炙}    $u{杏仁}$w{四十枚。去皮尖}    $u{生姜}$w{三两。切}    $u{大枣}$w{十枚。擘}    $u{石膏}$w{如鸡子大(碎)}</p>\n<p>\t上七味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。取微似汗。汗出多者。温粉扑之。一服汗者。停后服。若复服。汗多亡阳。遂$a{一作逆}虚。恶风烦躁。不得眠也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":20,"yaoCount":7,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","杏仁","生姜","大枣","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":600,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"40枚","weight":400,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚","weight":100,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大","weight":750,"suffix":"","showName":"石膏","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '20、$f{大青龙汤} 7味 $u{麻黄}$w{六两。去节} $u{桂枝}$w{二两。去皮} $u{甘草}$w{二两。炙} $u{杏仁}$w{四十枚。去皮尖} $u{生姜}$w{三两。切} $u{大枣}$w{十枚。擘} $u{石膏}$w{如鸡子大(碎)} 上七味。以水九升。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。取微似汗。汗出多者。温粉扑之。一服汗者。停后服。若复服。汗多亡阳。遂$a{一作逆}虚。恶风烦躁。不得眠也。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iX3eQYGte1p', 1, '{"title":"小青龙汤","description":"<p>21、$f{小青龙汤} 8味 </p>\n<p>$u{麻黄}$w{去节}    $u{芍药}    $u{细辛}    $u{干姜}    $u{甘草}$w{炙}    $u{桂枝}$w{各三两。去皮}    $u{五味子}$w{半升}    $u{半夏}$w{半升(洗)}</p>\n<p>\t上八味。以水一斗。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。若渴。去$u{半夏}。加$u{栝楼根}$w{三两}。若微利。去$u{麻黄}。加$u{荛花}。$w{如一鸡子。熬令赤色}。若噎者。去$u{麻黄}。加$u{附子}$w{一枚。炮}。若小便不利。少腹满者。去$u{麻黄}。加$u{茯苓}$w{四两}。若喘。去$u{麻黄}。加$u{杏仁}$w{半升。去皮尖。}【且荛花不治利。麻黄主喘。今此语反之。疑非仲景意。】$a{臣亿等谨按小青龙汤。大要治水。又按本草荛花下十二水。若水去。利则止也。又按千金。形肿者应内麻黄。乃内杏仁者。以麻黄发其阳故也。以此证之。岂非仲景意也。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":21,"yaoCount":13,"drinkNum":3,"yaoList":["麻黄","芍药","细辛","干姜","甘草","桂枝","五味子","半夏","栝楼根","荛花","附子","茯苓","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"$x{微利/噎者/小便不利少腹满者/喘者去麻黄)}三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":300,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":500,"suffix":"","showName":"五味子","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"$x{渴者去半夏)}半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '21、$f{小青龙汤} 8味 $u{麻黄}$w{去节} $u{芍药} $u{细辛} $u{干姜} $u{甘草}$w{炙} $u{桂枝}$w{各三两。去皮} $u{五味子}$w{半升} $u{半夏}$w{半升(洗)} 上八味。以水一斗。先煮麻黄。减二升。去上沫。内诸药。煮取三升。去滓。温服一升。若渴。去$u{半夏}。加$u{栝楼根}$w{三两}。若微利。去$u{麻黄}。加$u{荛花}。$w{如一鸡子。熬令赤色}。若噎者。去$u{麻黄}。加$u{附子}$w{一枚。炮}。若小便不利。少腹满者。去$u{麻黄}。加$u{茯苓}$w{四两}。若喘。去$u{麻黄}。加$u{杏仁}$w{半升。去皮尖。}【且荛花不治利。麻黄主喘。今此语反之。疑非仲景意。】$a{臣亿等谨按小青龙汤。大要治水。又按本草荛花下十二水。若水去。利则止也。又按千金。形肿者应内麻黄。乃内杏仁者。以麻黄发其阳故也。以此证之。岂非仲景意也。}', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GTZAUbfwDcQ', 1, '{"title":"干姜附子汤","description":"<p>22、$f{干姜附子汤} 2味 </p>\n<p>$u{干姜}$w{一两}    $u{附子}$w{一枚(生用。去皮。切八片)}</p>\n<p>\t上二味。以水三升。煮取一升。去滓。顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":22,"yaoCount":2,"drinkNum":1,"yaoList":["干姜","附子"],"fangList":[],"fangYaoList":[{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚生","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '2024-09-17T00:59:44.000Z', '22、$f{干姜附子汤} 2味 $u{干姜}$w{一两} $u{附子}$w{一枚(生用。去皮。切八片)} 上二味。以水三升。煮取一升。去滓。顿服。', '2024-09-17T00:59:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
