INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3BNFYQVdmoc', 1, '{"title":"真武汤","description":"<p>38、$f{真武汤} 5味 </p>\n<p>$u{茯苓}    $u{芍药}    $u{生姜}$w{各三两(切)}    $u{白术}$w{二两}    $u{附子}$w{一枚(炮。去皮。破八片)}</p>\n<p>\t上五味。以水八升。煮取三升。去滓。温服七合。日三服。若咳者。加$u{五味子}$w{半升}    $u{细辛}$w{一两}    $u{干姜}$w{一两}。若小便利者。去$u{茯苓}。若下利者。去$u{芍药}。加$u{干姜}$w{二两}。若呕者。去$u{附子}。加$u{生姜}。$w{足前为半斤。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":38,"yaoCount":8,"drinkNum":4,"yaoList":["茯苓","芍药","生姜","白术","附子","五味子","细辛","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"$x{小便利者去茯苓)}三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"$x{下利者去芍药)}三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两($x{呕者加生姜}至半斤)","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"$x{呕者去附子)}1枚炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T00:59:45.000Z', '2024-09-17T00:59:45.000Z', '2024-09-17T00:59:45.000Z', '38、$f{真武汤} 5味 $u{茯苓} $u{芍药} $u{生姜}$w{各三两(切)} $u{白术}$w{二两} $u{附子}$w{一枚(炮。去皮。破八片)} 上五味。以水八升。煮取三升。去滓。温服七合。日三服。若咳者。加$u{五味子}$w{半升} $u{细辛}$w{一两} $u{干姜}$w{一两}。若小便利者。去$u{茯苓}。若下利者。去$u{芍药}。加$u{干姜}$w{二两}。若呕者。去$u{附子}。加$u{生姜}。$w{足前为半斤。}', '2024-09-17T00:59:45.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
