INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03tx88fd0fL', 1, '{"title":"小建中汤","description":"<p>40、$f{小建中汤} 6味 </p>\n<p>$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}    $u{芍药}$w{六两}    $u{生姜}$w{三两。切}    $u{胶饴}$w{一升}</p>\n<p>\t上六味。以水七升。煮取三升。去滓。内饴。更上微火消解。温服一升。日三服。呕家不可用建中汤。以甜故也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":40,"yaoCount":6,"drinkNum":3,"yaoList":["桂枝","甘草","大枣","芍药","生姜","胶饴"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":600,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":1000,"suffix":"","showName":"胶饴","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '40、$f{小建中汤} 6味 $u{桂枝}$w{三两。去皮} $u{甘草}$w{二两。炙} $u{大枣}$w{十二枚。擘} $u{芍药}$w{六两} $u{生姜}$w{三两。切} $u{胶饴}$w{一升} 上六味。以水七升。煮取三升。去滓。内饴。更上微火消解。温服一升。日三服。呕家不可用建中汤。以甜故也。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I1T4d45FuOa', 1, '{"title":"大柴胡汤","description":"<p>41、$f{大柴胡汤} 7味 </p>\n<p>$u{柴胡}$w{半斤}    $u{黄芩}$w{三两}    $u{芍药}$w{三两}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{五两。切}    $u{枳实}$w{四枚。炙}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上七味。以水一斗二升。煮取六升。去滓。再煎。温服一升。日三服。【一方。加$u{大黄}$w{二两}。若不加。恐不为大柴胡汤。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":41,"yaoCount":8,"drinkNum":3,"yaoList":["柴胡","黄芩","芍药","半夏","生姜","枳实","大枣","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"4枚","weight":40,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '41、$f{大柴胡汤} 7味 $u{柴胡}$w{半斤} $u{黄芩}$w{三两} $u{芍药}$w{三两} $u{半夏}$w{半升(洗)} $u{生姜}$w{五两。切} $u{枳实}$w{四枚。炙} $u{大枣}$w{十二枚。擘} 上七味。以水一斗二升。煮取六升。去滓。再煎。温服一升。日三服。【一方。加$u{大黄}$w{二两}。若不加。恐不为大柴胡汤。】', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('45N8jZnTBWh', 1, '{"title":"柴胡加芒硝汤","description":"<p>42、$f{柴胡加芒硝汤} 8味 </p>\n<p>$u{柴胡}$w{二两十六铢}    $u{黄芩}$w{一两}    $u{人参}$w{一两}    $u{甘草}$w{一两。炙}    $u{生姜}$w{一两。切}    $u{半夏}$w{二十铢(本云五枚。洗)}    $u{大枣}$w{四枚。擘}    $u{芒硝}$w{二两}</p>\n<p>\t上八味。以水四升。煮取二升。去滓。内芒硝。更微煮沸。分温再服。不解更作。$a{臣亿等谨按金匮玉函方中。无芒消。别一方云。以水七升。下芒消二合。大黄四两。桑螵蛸五枚。煮取一升半。服五合。微下即愈。本云柴胡再服以解其外。余二升加芒消大黄桑螵蛸也。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":42,"yaoCount":8,"drinkNum":2,"yaoList":["柴胡","黄芩","人参","甘草","生姜","半夏","大枣","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"二两十六铢","weight":266,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"一两","weight":100,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":100,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两","weight":100,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"二十铢","weight":83,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"4枚","weight":40,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"二两","weight":200,"suffix":"","showName":"芒硝","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '42、$f{柴胡加芒硝汤} 8味 $u{柴胡}$w{二两十六铢} $u{黄芩}$w{一两} $u{人参}$w{一两} $u{甘草}$w{一两。炙} $u{生姜}$w{一两。切} $u{半夏}$w{二十铢(本云五枚。洗)} $u{大枣}$w{四枚。擘} $u{芒硝}$w{二两} 上八味。以水四升。煮取二升。去滓。内芒硝。更微煮沸。分温再服。不解更作。$a{臣亿等谨按金匮玉函方中。无芒消。别一方云。以水七升。下芒消二合。大黄四两。桑螵蛸五枚。煮取一升半。服五合。微下即愈。本云柴胡再服以解其外。余二升加芒消大黄桑螵蛸也。}', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EpHlIZutnfZ', 1, '{"title":"桃核承气汤","description":"<p>43、$f{桃核承气汤} 5味 </p>\n<p>$u{桃仁}$w{五十个。去皮尖}     $u{桂枝}$w{二两。去皮}  $u{大黄}$w{四两}     $u{甘草}$w{二两。炙}    $u{芒硝}$w{二两}</p>\n<p>\t上五味。以水七升。煮取二升半。去滓。内芒硝。更上火。微沸下火。先食。温服五合。日三服。当微利。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":43,"yaoCount":5,"drinkNum":5,"yaoList":["芒硝","甘草","桂枝","大黄","桃仁"],"fangList":[],"fangYaoList":[{"yaoId":"k2cI79Wat6h","amount":"50个","weight":500,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"二两","weight":200,"suffix":"","showName":"芒硝","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '43、$f{桃核承气汤} 5味 $u{桃仁}$w{五十个。去皮尖} $u{桂枝}$w{二两。去皮} $u{大黄}$w{四两} $u{甘草}$w{二两。炙} $u{芒硝}$w{二两} 上五味。以水七升。煮取二升半。去滓。内芒硝。更上火。微沸下火。先食。温服五合。日三服。当微利。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z8jM6j0arbe', 1, '{"title":"柴胡加龙骨牡蛎汤","description":"<p>44、$f{柴胡加龙骨牡蛎汤} 12味 </p>\n<p>$u{柴胡}$w{四两}    $u{龙骨}    $u{黄芩}    $u{生姜}$w{切}    $u{铅丹}    $u{人参}    $u{桂枝}$w{去皮}    $u{茯苓}$w{各一两半}    $u{半夏}$w{二合半(洗)}    $u{大黄}$w{二两}    $u{牡蛎}$w{一两半(熬)}    $u{大枣}$w{六枚。擘}</p>\n<p>\t上十二味。以水八升。煮取四升。内大黄。切如棋子。更煮一两沸。去滓。温服一升。【本云柴胡汤。今加龙骨等。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":44,"yaoCount":12,"drinkNum":4,"yaoList":["柴胡","龙骨","黄芩","生姜","铅丹","人参","桂枝","茯苓","半夏","大黄","牡蛎","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"四两","weight":400,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"一两半","weight":150,"suffix":"","showName":"龙骨","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"一两半","weight":150,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":150,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"E3Mbs1VE7cx","amount":"一两半","weight":150,"suffix":"","showName":"铅丹","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两半","weight":150,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两半","weight":150,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"一两半","weight":150,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"二合半","weight":250,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"二两","weight":200,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"一两半","weight":150,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"6枚","weight":60,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '44、$f{柴胡加龙骨牡蛎汤} 12味 $u{柴胡}$w{四两} $u{龙骨} $u{黄芩} $u{生姜}$w{切} $u{铅丹} $u{人参} $u{桂枝}$w{去皮} $u{茯苓}$w{各一两半} $u{半夏}$w{二合半(洗)} $u{大黄}$w{二两} $u{牡蛎}$w{一两半(熬)} $u{大枣}$w{六枚。擘} 上十二味。以水八升。煮取四升。内大黄。切如棋子。更煮一两沸。去滓。温服一升。【本云柴胡汤。今加龙骨等。】', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7Y20mM7x0vp', 1, '{"title":"桂枝去芍药加蜀漆牡蛎龙骨救逆汤","description":"<p>45、$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤} 7味 </p>\n<p>$u{桂枝}$w{三两。去皮}    $u{甘草}$w{二两。炙}    $u{生姜}$w{三两。切}    $u{大枣}$w{十二枚。擘}    $u{牡蛎}$w{五两(熬)}    $u{蜀漆}$w{三两(洗去腥)}    $u{龙骨}$w{四两}</p>\n<p>\t上七味。以水一斗二升。先煮蜀漆。减二升。内诸药。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加蜀漆牡蛎龙骨。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":45,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","甘草","生姜","大枣","牡蛎","蜀漆","龙骨"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"五两","weight":500,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"gFgG38KNuFm","amount":"三两","weight":300,"suffix":"","showName":"蜀漆","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"四两","weight":400,"suffix":"","showName":"龙骨","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '45、$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤} 7味 $u{桂枝}$w{三两。去皮} $u{甘草}$w{二两。炙} $u{生姜}$w{三两。切} $u{大枣}$w{十二枚。擘} $u{牡蛎}$w{五两(熬)} $u{蜀漆}$w{三两(洗去腥)} $u{龙骨}$w{四两} 上七味。以水一斗二升。先煮蜀漆。减二升。内诸药。煮取三升。去滓。温服一升。【本云桂枝汤。今去芍药。加蜀漆牡蛎龙骨。】', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DG3CU05x7UQ', 1, '{"title":"桂枝加桂汤","description":"<p>46、$f{桂枝加桂汤} 5味 </p>\n<p>$u{桂枝}$w{五两。去皮}    $u{芍药}$w{三两}    $u{生姜}$w{三两。切}    $u{甘草}$w{二两。炙}    $u{大枣}$w{十二枚。擘}</p>\n<p>\t上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加桂满五两所以加桂者。以能泄奔豚气也。】</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":46,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","生姜","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"五两","weight":500,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '46、$f{桂枝加桂汤} 5味 $u{桂枝}$w{五两。去皮} $u{芍药}$w{三两} $u{生姜}$w{三两。切} $u{甘草}$w{二两。炙} $u{大枣}$w{十二枚。擘} 上五味。以水七升。煮取三升。去滓。温服一升。【本云桂枝汤。今加桂满五两所以加桂者。以能泄奔豚气也。】', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
