INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q9DnzLOEg2K', 1, '{"title":"抵当汤","description":"<p>48、$f{抵当汤} 4味 </p>\n<p>$u{水蛭}$w{(熬)}    $u{虻虫}$w{各三十个(去翅足。熬)}    $u{桃仁}$w{二十个。去皮尖}    $u{大黄}$w{三两($u{酒}洗)}</p>\n<p>\t上四味。以水五升。煮取三升。去滓。温服一升。不下。更服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":48,"yaoCount":5,"drinkNum":3,"yaoList":["水蛭","虻虫","桃仁","大黄","酒"],"fangList":[],"fangYaoList":[{"yaoId":"biroLUs3POn","amount":"30个","weight":300,"suffix":"","showName":"水蛭","extraProcess":"切"},{"yaoId":"L1yNgzB2bxB","amount":"30个","weight":300,"suffix":"","showName":"虻虫","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"20个","weight":200,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"三两","weight":300,"suffix":"","showName":"大黄","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '48、$f{抵当汤} 4味 $u{水蛭}$w{(熬)} $u{虻虫}$w{各三十个(去翅足。熬)} $u{桃仁}$w{二十个。去皮尖} $u{大黄}$w{三两($u{酒}洗)} 上四味。以水五升。煮取三升。去滓。温服一升。不下。更服。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JaIRlIACjpM', 1, '{"title":"抵当丸","description":"<p>49、$f{抵当丸} 4味 </p>\n<p>$u{水蛭}$w{二十个(熬)}    $u{虻虫}$w{二十个(去翅足。熬)}    $u{桃仁}$w{二十五个。去皮尖}    $u{大黄}$w{三两}</p>\n<p>\t上四味。捣分四丸。以水一升。煮一丸。取七合。服之。晬时当下血。若不下者。更服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":49,"yaoCount":4,"drinkNum":4,"yaoList":["水蛭","虻虫","桃仁","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"biroLUs3POn","amount":"20个","weight":200,"suffix":"","showName":"水蛭","extraProcess":"切"},{"yaoId":"L1yNgzB2bxB","amount":"20个","weight":200,"suffix":"","showName":"虻虫","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"25个","weight":250,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"三两","weight":300,"suffix":"","showName":"大黄","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '49、$f{抵当丸} 4味 $u{水蛭}$w{二十个(熬)} $u{虻虫}$w{二十个(去翅足。熬)} $u{桃仁}$w{二十五个。去皮尖} $u{大黄}$w{三两} 上四味。捣分四丸。以水一升。煮一丸。取七合。服之。晬时当下血。若不下者。更服。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WSCP5XNOWCa', 1, '{"title":"大陷胸丸","description":"<p>50、$f{大陷胸丸} 6味 </p>\n<p>$u{大黄}$w{半斤}    $u{葶苈子}$w{半升(熬)}    $u{芒硝}$w{半升}    $u{杏仁}$w{半升(去皮尖,熬黑)}</p>\n<p>\t上四味。捣筛二味。内杏仁。芒硝。合研如脂。和散。取如弹丸一枚。别捣$u{甘遂末}$w{末一钱匕}    $u{白蜜}$w{二合}。水二升。煮取一升。温顿服之。一宿乃下。如不下。更服。取下为效。禁如药法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":50,"yaoCount":6,"drinkNum":50,"yaoList":["大黄","葶苈子","芒硝","杏仁","甘遂末","白蜜"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"半斤","weight":800,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"jD7lvOl6QAj","amount":"半升","weight":200,"suffix":"","showName":"葶苈子","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"半升","weight":500,"suffix":"","showName":"芒硝","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"半升约150枚","weight":1500,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"7nTRDUdzsoW","amount":"50钱匕","weight":500,"suffix":"","showName":"甘遂末","extraProcess":"切"},{"yaoId":"IHSagd4ikNY","amount":"二合","weight":100,"suffix":"","showName":"白蜜","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '50、$f{大陷胸丸} 6味 $u{大黄}$w{半斤} $u{葶苈子}$w{半升(熬)} $u{芒硝}$w{半升} $u{杏仁}$w{半升(去皮尖,熬黑)} 上四味。捣筛二味。内杏仁。芒硝。合研如脂。和散。取如弹丸一枚。别捣$u{甘遂末}$w{末一钱匕} $u{白蜜}$w{二合}。水二升。煮取一升。温顿服之。一宿乃下。如不下。更服。取下为效。禁如药法。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l6czJ9sN1Y6', 1, '{"title":"大陷胸汤","description":"<p>51、$f{大陷胸汤} 3味 </p>\n<p>$u{大黄}$w{六两。去皮}    $u{芒硝}$w{一升}    $u{甘遂}$w{一钱匕}</p>\n<p>\t上三味。以水六升。先煮大黄取二升。去滓。内芒硝。煮一两沸。内甘遂末。温服一升。得快利。止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":51,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","芒硝","甘遂"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"六两","weight":600,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"一升","weight":1000,"suffix":"","showName":"芒硝","extraProcess":"切"},{"yaoId":"7nTRDUdzsoW","amount":"二钱匕","weight":20,"suffix":"","showName":"甘遂","extraProcess":"切"}]}}', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '2024-09-17T00:59:46.000Z', '51、$f{大陷胸汤} 3味 $u{大黄}$w{六两。去皮} $u{芒硝}$w{一升} $u{甘遂}$w{一钱匕} 上三味。以水六升。先煮大黄取二升。去滓。内芒硝。煮一两沸。内甘遂末。温服一升。得快利。止后服。', '2024-09-17T00:59:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pECtdAmXSfp', 1, '{"title":"小陷胸汤","description":"<p>52、$f{小陷胸汤} 3味 </p>\n<p>$u{黄连}$w{一两}    $u{半夏}$w{半升(洗)}    $u{栝楼实}$w{大者一枚}</p>\n<p>\t上三味。以水六升。先煮栝楼。取三升。去滓。内诸药。煮取二升。去滓。分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":52,"yaoCount":3,"drinkNum":3,"yaoList":["黄连","半夏","栝楼实"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"一两","weight":100,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"9BxIgk2gITY","amount":"1枚","weight":100,"suffix":"","showName":"栝楼实","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '52、$f{小陷胸汤} 3味 $u{黄连}$w{一两} $u{半夏}$w{半升(洗)} $u{栝楼实}$w{大者一枚} 上三味。以水六升。先煮栝楼。取三升。去滓。内诸药。煮取二升。去滓。分温三服。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ArAqVZDXLKn', 1, '{"title":"文蛤散","description":"<p>53、$f{文蛤散} 1味 </p>\n<p>$u{文蛤}$w{五两}</p>\n<p>\t上一味。为散。以沸汤和一方寸匕服。汤用五合。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":53,"yaoCount":1,"drinkNum":3,"yaoList":["文蛤"],"fangList":[],"fangYaoList":[{"yaoId":"FCFRnbDhdjZ","amount":"五两","weight":500,"suffix":"","showName":"文蛤","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '53、$f{文蛤散} 1味 $u{文蛤}$w{五两} 上一味。为散。以沸汤和一方寸匕服。汤用五合。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rU5BWw0lP2a', 1, '{"title":"三物小白散","description":"<p>54、$f{三物小白散} 3味 </p>\n<p>$u{桔梗}$w{三分}    $u{巴豆}$w{一分(去皮心。熬黑。研如脂)}    $u{贝母}$w{三分}</p>\n<p>\t上三味为散。内巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":54,"yaoCount":4,"drinkNum":10,"yaoList":["桔梗","巴豆","贝母","芍药"],"fangList":[],"fangYaoList":[{"yaoId":"t7DkIvGNO8b","amount":"三分","weight":75,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":"1n7R7kiLFv1","amount":"一分","weight":25,"suffix":"","showName":"巴豆","extraProcess":"切"},{"yaoId":"lzOM54GtZJW","amount":"三分","weight":75,"suffix":"","showName":"贝母","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '54、$f{三物小白散} 3味 $u{桔梗}$w{三分} $u{巴豆}$w{一分(去皮心。熬黑。研如脂)} $u{贝母}$w{三分} 上三味为散。内巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TMZrDeeEsLl', 1, '{"title":"柴胡桂枝汤","description":"<p>55、$f{柴胡桂枝汤} 9味 </p>\n<p>$u{桂枝}$w{去皮}    $u{芍药}$w{一两半}    $u{黄芩}$w{一两半}    $u{人参}$w{一两半}    $u{甘草}$w{一两。炙}    $u{半夏}$w{二合半(洗)}    $u{生姜}$w{一两半。切}    $u{大枣}$w{六枚。擘}    $u{柴胡}$w{四两}</p>\n<p>\t上九味。以水七升。煮取三升。去滓。温服一升。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":55,"yaoCount":9,"drinkNum":3,"yaoList":["桂枝","芍药","黄芩","人参","甘草","半夏","生姜","大枣","柴胡"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"一两半","weight":150,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"一两半","weight":150,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"一两半","weight":150,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两半","weight":150,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"二合半","weight":250,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":150,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"6枚","weight":60,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"JMfcgoRTH0J","amount":"四两","weight":400,"suffix":"","showName":"柴胡","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '55、$f{柴胡桂枝汤} 9味 $u{桂枝}$w{去皮} $u{芍药}$w{一两半} $u{黄芩}$w{一两半} $u{人参}$w{一两半} $u{甘草}$w{一两。炙} $u{半夏}$w{二合半(洗)} $u{生姜}$w{一两半。切} $u{大枣}$w{六枚。擘} $u{柴胡}$w{四两} 上九味。以水七升。煮取三升。去滓。温服一升。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bwSU5ipn0rO', 1, '{"title":"柴胡桂枝干姜汤","description":"<p>56、$f{柴胡桂枝干姜汤} 7味 </p>\n<p>$u{柴胡}$w{半斤}    $u{桂枝}$w{三两。去皮}    $u{干姜}$w{二两}    $u{栝楼根}$w{四两}    $u{黄芩}$w{三两}    $u{牡蛎}$w{二两(熬)}    $u{甘草}$w{二两。炙}</p>\n<p>\t上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。初服微烦。复服汗出便愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":56,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","桂枝","干姜","栝楼根","黄芩","牡蛎","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":200,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":400,"suffix":"","showName":"栝楼根","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"二两","weight":200,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '56、$f{柴胡桂枝干姜汤} 7味 $u{柴胡}$w{半斤} $u{桂枝}$w{三两。去皮} $u{干姜}$w{二两} $u{栝楼根}$w{四两} $u{黄芩}$w{三两} $u{牡蛎}$w{二两(熬)} $u{甘草}$w{二两。炙} 上七味。以水一斗二升。煮取六升。去滓。再煎取三升。温服一升。日三服。初服微烦。复服汗出便愈。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
