INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BkIRTqlmupT', 1, '{"title":"十枣汤","description":"<p>58、$f{十枣汤} 4味 </p>\n<p>$u{芫花}$w{(熬)}    $u{甘遂}    $u{大戟}    $u{大枣}$w{十枚(先煮)}</p>\n<p>\t上三味等分。各别捣为散。以水一升半。先煮大枣肥大者十枚。取八合。去滓。内药末。$a{强人服一钱匕。羸人服半钱。}温服之。$a{平旦服。}若下少病不除者。明日更服。$a{加半钱。}得快下利后。糜粥自养。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"q6u5siNb2hT","no":58,"yaoCount":4,"drinkNum":1,"yaoList":["芫花","甘遂","大戟","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"ME53uu1RfSN","amount":"1/3钱匕","weight":3,"suffix":"","showName":"芫花","extraProcess":"切"},{"yaoId":"7nTRDUdzsoW","amount":"1/3钱匕","weight":3,"suffix":"","showName":"甘遂","extraProcess":"切"},{"yaoId":"gZLQX87OyZG","amount":"1/3钱匕","weight":3,"suffix":"","showName":"大戟","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚肥大者","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '2024-09-17T00:59:47.000Z', '58、$f{十枣汤} 4味 $u{芫花}$w{(熬)} $u{甘遂} $u{大戟} $u{大枣}$w{十枚(先煮)} 上三味等分。各别捣为散。以水一升半。先煮大枣肥大者十枚。取八合。去滓。内药末。$a{强人服一钱匕。羸人服半钱。}温服之。$a{平旦服。}若下少病不除者。明日更服。$a{加半钱。}得快下利后。糜粥自养。', '2024-09-17T00:59:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
